select 'b3e91f6c47d2', m.mx + row_number() over (order by t.i), t.e->>'lib', t.e->'chunk'
  from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "dig-ca-damage-1", "state": "CA", "tier": "core", "title": "California 811: emergencies and what to do when a line is hit", "topic": "811 emergencies and what to do when a line is hit", "text": "California, line hit or found damaged (Gov. Code 4216.4(c)): 1) Call 911 right away if the damage is to a gas or hazardous liquid line and there is an \"escape of any flammable, toxic, or corrosive gas or liquid\" (also for high priority lines). 2) Call the operator right away for any damage, even a nick or scraped coating. 3) Notify the regional 811 center within 48 hours. Keep people away, do not try to fix or pinch the line, do not cover it up. Emergency digging: the 2 working day notice does not apply in an emergency, defined as \"a sudden, unexpected occurrence, involving a clear and imminent danger, demanding immediate action\" to prevent loss of life, health, property or essential public services (4216(f)). Call 811 for an emergency ticket as soon as you can. An expired ticket or marks you can no longer see are not emergencies: stop and call for a renewal or remark.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-4/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ca-penalties-1", "state": "CA", "tier": "core", "title": "California 811: fines and who enforces", "topic": "811 penalties, exemptions and design tickets", "text": "California fines for breaking the dig law (Gov. Code 4216.6(a)): a negligent violation, up to $10,000; a knowing and willful violation, up to $50,000; a knowing and willful violation that damages a gas or hazardous liquid line and lets flammable, toxic or corrosive gas or liquid escape, up to $100,000. Who enforces: the Contractors State License Board for contractors; the Public Utilities Commission for gas, electric and water corporations; the State Fire Marshal for hazardous liquid pipelines; local boards for local agencies; and the Underground Safe Excavation Board (\"Dig Safe Board\") for everyone else, since July 1, 2020. The Attorney General or a district attorney can also sue. On top of fines, the excavator can owe the repair cost and other damages. A contractor's license can be on the line with the CSLB. The Board also investigates near misses and damages reported to it.", "source": "Cal. Gov. Code 4216.6 (california.public.law copy, section updated Jan 1, 2025)", "url": "https://california.public.law/codes/ca_gov't_code_section_4216.6", "checked": "2026-11-20", "edition": "Section as updated January 1, 2025", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-az-tickets-1", "state": "AZ", "tier": "core", "title": "Arizona 811: marks good 15 working days, renewals, large projects (2026 law)", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Arizona ticket life: \"The marking required by subsection B of this section is valid for fifteen working days from the date of the marking\" (A.R.S. 40-360.22(J)). To keep digging past that, notify \"at least two working days before the end of the validity period.\" The Corporation Commission's page says to call 811 \"to have your marks refreshed.\" Whether the refresh gets a new ticket number is not confirmed. Landlords (apartment communities, mobile home parks) get up to 10 working days to mark their own lines. Operators answer through the interactive positive response system; check it before digging. If an operator can't finish marking in time it must tell you promptly and send someone to the site. A line is not abandoned until the operator tells you it is: \"the excavator shall not treat the underground facility as abandoned until the excavator has received notification.\" New in 2026 (SB 1137, Laws 2026 ch. 147): for a large project, notify the one-call center \"not less than 15 business days or 21 calendar days\" before the start to set a coordination meeting, with a phased ticket plan agreed in the system. The effective date was not confirmed in the summary read.", "source": "A.R.S. 40-360.22 (azleg.gov); 2026 SB 1137 House summary; azcc.gov AZ 811 page", "url": "https://azleg.gov/ars/40/00360-22.htm", "checked": "2026-11-20", "edition": "Statute as posted on azleg.gov, read Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "new ticket number on refresh; SB 1137 effective date"}},
{"lib": "field", "chunk": {"id": "dig-az-marks-1", "state": "AZ", "tier": "core", "title": "Arizona 811: careful digging within 24 inches, white lining", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Arizona has no section called \"tolerance zone.\" The rule is in the definition of \"carefully\" (A.R.S. 40-360.21): within 24 inches of a marked facility, the facility is \"carefully exposed with hand tools, and the uncovered facility is supported and protected.\" Having the marks \"does not excuse any person making any excavation from doing so in a careful and prudent manner\" (40-360.23(A)). If you find a line that was not marked or was marked wrong, tell the operator (40-360.23(B)). White lining: you \"shall clearly and carefully mark with white lining the area that is requested to be excavated\" (40-360.22(C)). Marking colors follow the Commission's color code (A.A.C. R14-2-106), the same as the national APWA colors. Landscape irrigation lines 2 inches or smaller are not \"underground facilities\" under this law, and private lines past the meter are not marked by the utility.", "source": "A.R.S. 40-360.21 to 40-360.28 (azleg.gov; statute copy in Southwest Gas \"Arizona Dig Law\" booklet, rev. Aug 2017)", "url": "https://www.swgas.com/1409223424748/Arizona-Dig-Law.pdf", "checked": "2026-11-20", "edition": "Statute text as printed in the Aug 2017 booklet; 40-360.22 checked on azleg.gov Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-az-damage-1", "state": "AZ", "tier": "core", "title": "Arizona 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Arizona, line hit (A.R.S. 40-360.24): gas or hazardous material line damaged: \"immediately notify the underground facilities operator and 911 or the local emergency response agency.\" Any other damage: tell the operator right away and do not try to repair it. \"The excavation shall be left open until the arrival of representatives of the underground facilities operator.\" Fines (40-360.28): \"a civil penalty in an amount not to exceed five thousand dollars,\" and the violator owes the repair cost (40-360.26) and the other side's attorney fees if it loses (40-360.27). The fine section does not apply (40-360.28(F)): during \"an emergency which involves danger to life, health or property\" if reasonable precautions are taken; to farm operations and resource extraction; to hand-tool gardening or tilling on your own lot. There is no depth below which you may dig without calling.", "source": "A.R.S. 40-360.21 to 40-360.28 (azleg.gov; statute copy in Southwest Gas \"Arizona Dig Law\" booklet, rev. Aug 2017)", "url": "https://www.swgas.com/1409223424748/Arizona-Dig-Law.pdf", "checked": "2026-11-20", "edition": "Statute text as printed in the Aug 2017 booklet; fine amount also on azcc.gov, Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-nv-tickets-1", "state": "NV", "tier": "core", "title": "Nevada 811: ticket types, two renewals, what to do after", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Nevada ticket life (NAC 455.165): good \"for 28 calendar days after the date and time that the excavator provided the notification.\" You may ask to extend by another 28 calendar days, and \"An excavator may not request more than two extensions.\" If more time is needed after the original and both extensions, \"the excavator shall submit a new notification\" under NRS 455.110, which means a new ticket with the normal 2 working days' wait. Call it in at least 2 working days before the second renewal runs out so there is no gap. Renew by the end of day 28 and only if the marks are still clear. Ticket only the area you can reasonably dig within 14 calendar days (NAC 455.115). Ticket types in the USA North handbook: locate request; Renewal; Re-Mark (marks gone or unclear); No Response (an operator did not answer; you can resend every hour); Next Job Phase (copies the last ticket for the next section); Pothole ticket; Damage or Exposed notice; Emergency. A ticket should cover no more than half a mile. There is no project or long-term ticket. Designers should not open locate tickets for design; use the Project Design lookup to get operator contacts.", "source": "NAC 455.165, 455.115 (leg.state.nv.us, rev. Aug 2026); USA North 811 Nevada Excavation Handbook (Jan 2025) pp. 5-8", "url": "https://www.leg.state.nv.us/nac/NAC-455.html", "checked": "2026-11-20", "edition": "NAC 455 as revised August 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-nv-marks-1", "state": "NV", "tier": "core", "title": "Nevada 811: hand tools within 24 inches, white marking, positive response", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Nevada hand dig rule, from the USA North handbook (p. 4): use hand tools only, to expose the line and find its exact location, when digging within 24 inches on either side of the outside diameter of the line. Report any contact, scrape, dent or nick to the operator. White marking (p. 3): on pavement, outline the dig with white spray chalk, water-based UV paint or something else that is not permanent. On dirt use white flags, stakes or whiskers. Marks follow the APWA uniform color code. Positive response: check Electronic Positive Response at usanorth811.org/epr before digging. If a member has not answered by the legal start time, send a No Response notification naming the member; if there is still nothing after an hour you may send it again each hour. Operators have 2 working days to mark, or a time you both agree to (NRS 455.130).", "source": "USA North 811 Nevada Excavation Handbook (rev. Jan 2025) pp. 3-8, 21; NRS 455.110; NAC 455.165", "url": "https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf", "checked": "2026-11-20", "edition": "Handbook revised January 2025", "confidence": "high", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-nv-damage-1", "state": "NV", "tier": "core", "title": "Nevada 811: emergencies and line hits", "topic": "811 emergencies and what to do when a line is hit", "text": "Nevada, line hit: the excavator \"shall immediately notify the operator\" of the damaged line (handbook p. 6, from NRS 455). USA North 811 takes Damage or Exposed notices and can give the operator's emergency number. If there is danger, call 911. Emergency digging: an emergency is \"a sudden, unexpected occurrence that involves clear and imminent danger\" (NRS 455.090). The excavator must tell the local public service agencies or 911 and the operator, and take reasonable steps to protect the lines. Send an Emergency notification to the center. Fine amounts are not in the handbook and were not confirmed from NRS 455.170 in this pass; the Public Utilities Commission of Nevada enforces the law.", "source": "USA North 811 Nevada Excavation Handbook (rev. Jan 2025) pp. 3-8, 21; NRS 455.110; NAC 455.165", "url": "https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf", "checked": "2026-11-20", "edition": "Handbook revised January 2025", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "fine amounts (NRS 455.170)"}},
{"lib": "field", "chunk": {"id": "dig-tx-tickets-1", "state": "TX", "tier": "core", "title": "Texas 811: ticket life 14 working days, refresh, second notice", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Texas pipeline locate tickets (16 TAC 18.1, 18.3, 18.4): a line locate ticket lasts 14 working days unless the excavator and operator agree to something else in writing. A working day is \"Every day that is not a Saturday, a Sunday, or a legal holiday.\" When the work is not finished, \"the excavator shall refresh the ticket by giving the notice,\" limited to the area still to be dug. Texas811 calls this an Update (or Update and Remark): it is \"sent with a two-business day notice,\" and \"If the most recent ticket is over 30 days old, a new ticket must be created.\" Whether an update prints a new ticket number is not confirmed. No positive response by the start time: you \"shall not begin excavating until a second notice is given.\" If \"there is no positive response within four hours, the excavator may begin excavating\" (18.4(e)-(f)). Report the second call, and any operator that still did not answer, to the Railroad Commission through TDRF (18.11(d)). Protect the marks from the day you start until they are no longer needed (18.4(g)).", "source": "16 TAC 18.1, 18.3, 18.4, 18.11 (eff. Feb 12, 2018); Texas811 help article \"Submitting an Update or Update & Remark\"", "url": "https://www.law.cornell.edu/regulations/texas/16-Tex-Admin-Code-SS-18-4", "checked": "2026-11-20", "edition": "Sections as amended effective February 12, 2018", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "new ticket number on an update"}},
{"lib": "field", "chunk": {"id": "dig-tx-marks-1", "state": "TX", "tier": "core", "title": "Texas 811: tolerance zone 18 inches plus half the pipe, hand digging, white lining", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Texas tolerance zone for pipelines (16 TAC 18.2): \"Half the nominal diameter of the underground pipeline plus a minimum of 18 inches on either side\" of the outside edge. The one-call law itself sets no zone for water, sewer, power or telecom; Texas811 teaches 18 inches for those. Inside the zone, use reasonable care (18.10): hand digging where practical, soft digging, vacuum excavation, pneumatic hand tools. White lining (18.3): required \"When an excavation site cannot be clearly identified and described on a line locate ticket.\" Mark it before you call and before the locator comes. Marks use the APWA color code and are spaced no more than 20 feet apart. Positive response: the operator marks the line or gives an \"all clear\" or \"no conflict.\" The pipeline rule does not cover digging that goes no deeper than 16 inches (18.1(d)); tilling deeper than 16 inches is covered.", "source": "16 TAC 18.1, 18.2, 18.3, 18.6, 18.8, 18.10 (Railroad Commission, eff. Feb 12, 2018)", "url": "https://www.rrc.texas.gov/media/ap2ck4pb/chapter18-all-effective-feb12-2018.pdf", "checked": "2026-11-20", "edition": "16 TAC ch. 18 as in effect Feb 12, 2018", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-tx-damage-1", "state": "TX", "tier": "core", "title": "Texas 811: pipeline hits: 1 hour notice, 911, 30-day report, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "Texas, pipeline hit (16 TAC 18.4(h), 18.11): notify the operator through the notification center (811) \"at the earliest practical moment but not later than one hour following the damage incident.\" You \"shall not cover the exposed pipeline without approval of the operator.\" If the damage releases flammable, toxic or corrosive gas, hazardous liquid or carbon dioxide, \"promptly report the release to appropriate emergency response authorities by calling 911.\" File a Texas Damage Reporting Form (TDRF) with the Railroad Commission \"within 30 days of the incident.\" The operator files one too. Fines (18.12 guideline tables): typical penalties include $2,000 for not filing the TDRF and $2,500 for not notifying the center or for not using reasonable care in the tolerance zone, with add-ons of $5,000 to $25,000 for aggravating factors. Emergency: a situation that endangers life, health or property, or where a service outage forces immediate action; call 811 for an emergency ticket.", "source": "16 TAC 18.4, 18.11, 18.12 (Railroad Commission, eff. Feb 12, 2018)", "url": "https://www.law.cornell.edu/regulations/texas/16-Tex-Admin-Code-SS-18-11", "checked": "2026-11-20", "edition": "Sections as amended effective February 12, 2018", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-fl-tickets-1", "state": "FL", "tier": "core", "title": "Florida 811: ticket life 30 days, positive response, no-show rule", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Florida ticket life (556.105(1)(c)): the information is valid for 30 calendar days. If the work is not finished, 556.114(2) says to \"provide a subsequent notice to the system\" for only the area still to be dug. Sunshine 811 says: \"When you need to renew a standard ticket, do not include any areas that are finished.\" Operators must post a positive response within 2 full business days (10 for underwater). The excavator must verify the positive responses before digging (556.105(9)(c)). If an operator has not marked in the time allowed, the excavator may go ahead using reasonable care and detection equipment or other acceptable means to find the lines (556.105(6)(a)). If you can see there is a line there and it is not marked and has no positive response, contact the operator. No demolition until lines are marked or removed. High-priority lines (556.116): gas and hazardous liquid pipelines the operator calls critical. If you will dig within 15 feet of one and the operator told you so, give the operator your start date and time before digging. Design help: an operator answers a design request within 20 business days after its fee is paid (556.112).", "source": "Fla. Stat. ch. 556 (2025): 556.102, 556.105, 556.107, 556.108, 556.109, 556.114, 556.116", "url": "https://flsenate.gov/Laws/Statutes/2025/Chapter556/All", "checked": "2026-11-20", "edition": "2025 Florida Statutes", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-fl-marks-1", "state": "FL", "tier": "core", "title": "Florida 811: tolerance zone 24 inches, soft digging, premarking", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Florida tolerance zone (556.102): 24 inches from the outer edge of either side of the marked underground facility. Inside the zone the excavator must \"use increased caution to protect underground facilities\" (556.105(5)(c)). The law lists hand digging, pot holing, soft digging and vacuum excavation. Any mechanized equipment in the zone must be supervised by the excavator. Premarking (556.102, 556.114(3)): outline the dig with \"white paint, white stakes, or other similar white markings.\" It is required when the site can't otherwise be identified, unless both sides agree otherwise or it would get in the way of traffic or people walking. Operators mark with the APWA Uniform Color Code for Utilities (556.105(10)). Business days are Monday to Friday, not the listed holidays.", "source": "Fla. Stat. ch. 556 (2025): 556.102, 556.105, 556.107, 556.108, 556.109, 556.114, 556.116", "url": "https://flsenate.gov/Laws/Statutes/2025/Chapter556/All", "checked": "2026-11-20", "edition": "2025 Florida Statutes", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-fl-damage-1", "state": "FL", "tier": "core", "title": "Florida 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Florida, line hit (556.105(12)): \"immediately notify the member operator\" of any contact or damage. If gas or another regulated hazardous substance escapes, \"immediately report the contact or damage by calling the 911 emergency telephone number.\" Stop digging that could do more damage until it is repaired. Incidents with high-priority lines go to Sunshine 811 and the State Fire Marshal within 24 hours. Emergency (556.109): \"a clear and present danger to life or property,\" escaping substances, or loss of vital service. Notify the system or operator as early as you can. Calling in a false emergency is an infraction. Fines (556.107): \"$500 plus court costs for each infraction\"; $2,500 plus court costs for violations involving hazardous material pipelines; up to $50,000 for a high-priority line incident (556.116). Fire marshals, fire chiefs, police and code officers can write the citation. Exempt (556.108): an owner digging on a single-family lot \"only up to a depth of 10 inches\"; normal farm work off rights-of-way; surveying and pest control 18 inches or less.", "source": "Fla. Stat. ch. 556 (2025): 556.102, 556.105, 556.107, 556.108, 556.109, 556.114, 556.116", "url": "https://flsenate.gov/Laws/Statutes/2025/Chapter556/All", "checked": "2026-11-20", "edition": "2025 Florida Statutes", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-wa-tickets-1", "state": "WA", "tier": "core", "title": "Washington 811: marks last 45 days, positive response, large projects", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Washington ticket rules (RCW 19.122.030): notice 2 to 10 full business days before the work-to-begin date, unless you and the operators agree otherwise in writing. A business day is \"any day other than Saturday, Sunday, or a legal local, state, or federal holiday.\" Markings \"expire forty-five calendar days from the date that the excavator provided notice.\" For digging after that, \"an excavator must provide additional notice to a one-number locator service.\" There is no renewal: it is a new ticket with the normal wait. The excavator must keep the marks accurate for 45 days or the length of the job, whichever is shorter. Positive response is required since January 1, 2026: no digging until every operator has answered. Large project means \"a project that exceeds seven hundred linear feet.\" On large projects or multiple sites you must take reasonable steps to confer with the operators before each phase. Design locating is for planning only and can't be used to dig.", "source": "RCW 19.122.020, .030, .031, .040, .050, .053, .055, .070 (through Laws 2025 c 292)", "url": "https://lawfilesext.leg.wa.gov/law/RCWPDF/RCW%20%2019%20%20TITLE/RCW%20%2019%20.122%20%20CHAPTER/RCW%20%2019%20.122%20%20COMBINEDCHAPTER.pdf", "checked": "2026-11-20", "edition": "RCW as amended through Laws of 2025 chapter 292", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-wa-marks-1", "state": "WA", "tier": "core", "title": "Washington 811: 24-inch accuracy, precise location, white lining", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Washington does not use the words \"tolerance zone.\" Operators must mark with \"reasonable accuracy,\" which means \"location within twenty-four inches of the outside dimensions of both sides of an underground facility\" (RCW 19.122.020). The excavator must \"Determine the precise location of underground facilities\" that have been marked and use safe and careful methods, which the law lists as \"hand digging when practical,\" vacuum excavation and pneumatic hand tools (19.122.040). Directional boring: physically expose the marked lines you will cross; no blind boring. White lining can be \"any white paint, flags, stakes, whiskers, or other locally accepted method\" (19.122.020). Marks follow the current APWA color code. Plan the work to keep damage and interference low, and keep the marks for the life of the job.", "source": "RCW 19.122.020, .030, .031, .040, .050, .053, .055, .070 (through Laws 2025 c 292)", "url": "https://lawfilesext.leg.wa.gov/law/RCWPDF/RCW%20%2019%20%20TITLE/RCW%20%2019%20.122%20%20CHAPTER/RCW%20%2019%20.122%20%20COMBINEDCHAPTER.pdf", "checked": "2026-11-20", "edition": "RCW as amended through Laws of 2025 chapter 292", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-wa-damage-1", "state": "WA", "tier": "core", "title": "Washington 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Washington, line hit (RCW 19.122.050, .053): notify the operator and the one-number locator service (811). If the damage causes an emergency, call 911 too. Do not bury a damaged line until it is repaired or relocated. Report the damage to the UTC \"within forty-five days of the damage event.\" Emergency (19.122.020, .031): \"any condition constituting a clear and present danger to life, health, or property,\" or certain unplanned outages. No white lining or advance notice needed, but notify 811 \"at the earliest practicable opportunity.\" Fines: up to $1,000 for a first violation and up to $5,000 for each later one within 3 years (19.122.070); up to $25,000 per violation if you break the law and damage a gas or hazardous liquid line (19.122.055). No ticket needed (19.122.031): digging less than 12 inches deep on private noncommercial property by the owner or occupant; farm tilling less than 12 inches in an easement or 20 inches outside one; road and ditch maintenance less than 6 inches below original grade; bar holes less than 12 inches. The damage rules still apply.", "source": "RCW 19.122.020, .030, .031, .040, .050, .053, .055, .070 (through Laws 2025 c 292)", "url": "https://lawfilesext.leg.wa.gov/law/RCWPDF/RCW%20%2019%20%20TITLE/RCW%20%2019%20.122%20%20CHAPTER/RCW%20%2019%20.122%20%20COMBINEDCHAPTER.pdf", "checked": "2026-11-20", "edition": "RCW as amended through Laws of 2025 chapter 292", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-or-tickets-1", "state": "OR", "tier": "core", "title": "Oregon 811: ticket life changed to 30 days in 2026 (was 45), no renewals", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Oregon ticket life: the 2026 Addendum to the Oregon Standards Manual (Oregon Utility Notification Center, March 12, 2026) lists a change to OAR 952-001-0010(23) that shortens ticket life \"from 45 days to 30 days,\" effective January 8, 2026. Copies of the rule dated through mid-2025 read \"the 45 calendar day period after an excavator provides notice,\" and the Center's FAQ page still said 45 on Nov 20, 2026. The official current rule text was not confirmed in this pass, so treat 30 days as the safe number and ask Oregon 811. There is no renewal. The rule says not to keep digging after ticket life ends \"unless you re-notify the Center\" (0090): that is a new locate request with the normal 2 full business days' notice. Do not start more than 10 business days after the notice without re-notifying. Keep the marks for the life of the job or of the ticket, whichever is shorter. Marks gone: stop and ask the Center for a remark. There is no legal \"priority\" locate. Less than 2 business days' notice is only for emergencies (0060).", "source": "OAR 952-001-0010, -0050, -0070, -0090 (Oregon Utility Notification Center); 2026 Addendum to the Oregon Standards Manual (Mar 12, 2026)", "url": "https://digsafelyoregon.com/wp-content/uploads/2026/03/2026-Addendum-to-the-Oregon-Standards-Manual_Final.pdf", "checked": "2026-11-20", "edition": "2026 Addendum, last updated March 12, 2026", "effective": "2026-01-08", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life 30 vs 45 days: official current rule text not opened"}},
{"lib": "field", "chunk": {"id": "dig-or-marks-1", "state": "OR", "tier": "core", "title": "Oregon 811: tolerance zone 24 inches, non-invasive methods, pre-marking", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Oregon tolerance zone: \"the area within 24 inches surrounding the outside dimensions of all sides of an underground facility\" (OAR 952-001-0010). Inside it you must \"Employ hand tools or other non-invasive methods\" to find the exact location of the line (0090(3)). The 2026 Addendum says non-invasive methods now include \"hand digging, air cutting, vacuum excavation, and hydro vacuum excavation.\" Directional drilling: watch the drill head and back reamer by eye as they pass through the tolerance zone. Give the lines the side and bottom support they need. Pre-marking in white is required by rule 0040 unless an exemption applies. If you find a line where the operator said there was none, tell the Center before going on and use extreme care. If an operator requires its own monitor at a critical line, don't start without the monitor or the operator's OK. 2026 change: work inside a meter box or vault that does not dig below its base no longer needs a ticket.", "source": "OAR 952-001-0010, -0040, -0090 (oregon.public.law / Justia copies); 2026 Addendum to the Oregon Standards Manual", "url": "https://oregon.public.law/rules/oar_952-001-0090", "checked": "2026-11-20", "edition": "Rule copies current to mid-2025; 2026 Addendum dated March 12, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-or-damage-1", "state": "OR", "tier": "core", "title": "Oregon 811: line hits, emergencies, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Oregon, line hit (OAR 952-001-0090(6)): notify the operator immediately. For an emergency, or a release of gas or hazardous liquid from a pipeline, call 911 and take reasonable steps to keep the public safe. You \"must not bury damaged underground facilities without the consent of the operator.\" Emergency (0010): \"an occurrence involving an immediate danger, demanding prompt action to prevent loss of life\" or to limit property damage, or to keep essential public services or customer service on, as decided by the emergency agency or the operator. Not \"excavation,\" so no ticket: sidewalk, road and ditch maintenance less than 12 inches deep that does not lower the original grade or ditch flow line; farm tilling on private land outside recorded utility easements. Fine amounts are set in ORS 757.993 and were not confirmed in this pass; the Public Utility Commission enforces.", "source": "OAR 952-001-0010, -0090 (oregon.public.law / Justia copies, current to mid-2025)", "url": "https://oregon.public.law/rules/oar_952-001-0090", "checked": "2026-11-20", "edition": "Rule copies current to mid-2025", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "fine amounts (ORS 757.993)"}},
{"lib": "field", "chunk": {"id": "dig-co-tickets-1", "state": "CO", "tier": "core", "title": "Colorado 811: ticket types, 30-day marks, updates", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Colorado ticket types (Colorado 811 handbook pp. 6-13): Normal (2 full business days ahead); Multiple Day (encouraged for jobs over 1,000 linear feet in populated areas); Emergency; Damage; Non-Compliance (you are asking for a response in less than 2 full business days); Excavator Re-Notification (a member did not answer or the locate is incomplete); Relocate/Refresh (marks no longer visible); Meet; Cancel; Engineering and Subsurface Utility Engineering (design only, never for digging; owners answer within 10 business days). Life: \"Locate marks are only valid for thirty (30) days from the ticket's due date\" or until no longer visible. The excavator \"shall notify Colorado 811 at least two (2) business days\" before that ends, and \"A new ticket must be processed after this time has expired.\" An Update Lite can be used on a ticket processed in the last 30 calendar days when nothing on it changes. Emergency tickets: members answer within 1 hour in business hours, 2 hours after hours. Meets: if a member is 15 minutes late with no contact, send a Re-Notification. Whether an update gets a new ticket number is not confirmed.", "source": "Colorado 811 Excavator Handbook (last update Nov 2022) pp. 5-23, 27-45; C.R.S. 9-1.5-103", "url": "https://a-us.storyblok.com/f/1021538/x/160e66dfe5/excavator-handbook.pdf", "checked": "2026-11-20", "edition": "Handbook last updated November 2022", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "new ticket number on an update"}},
{"lib": "field", "chunk": {"id": "dig-co-marks-1", "state": "CO", "tier": "core", "title": "Colorado 811: tolerance zone 18 inches, non-destructive digging, positive response", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Colorado tolerance zone: the width of the underground line plus 18 inches on each side (handbook p. 18; C.R.S. 9-1.5-103). Inside it use non-destructive digging only, such as hand digging or vacuum excavation. Power equipment there can damage the line. Pre-marking the dig area in white paint is highly recommended; the statute calls for white marks on a hard surface when the area can't be described. Owners must mark with the APWA color code. Positive response: verify the positive response of every member listed on the ticket before you dig. If a member has not responded by the locate-by date, send an Excavator Re-Notification before going ahead. Marks gone or unclear: ask for a Relocate/Refresh rather than guessing.", "source": "Colorado 811 Excavator Handbook (last update Nov 2022) pp. 5-23, 27-45; C.R.S. 9-1.5-103", "url": "https://a-us.storyblok.com/f/1021538/x/160e66dfe5/excavator-handbook.pdf", "checked": "2026-11-20", "edition": "Handbook last updated November 2022", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-co-damage-1", "state": "CO", "tier": "core", "title": "Colorado 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Colorado, line hit (handbook pp. 7, 21): stop digging and notify Colorado 811 and the operator immediately. Gas release: \"evacuate the area immediately and call 911,\" then 811 and the operator. A Damage ticket reports a damaged or accidentally exposed line. Emergency ticket: when \"immediate excavation is necessary to prevent the loss of life\" or serious damage. Say what the emergency is and any hazards on site. They can be filed any hour. Fines (handbook p. 40, Safety Commission table, highest in each tier): minor violations $250 for a first up to $5,000 for a fourth; moderate $1,000 up to $25,000; major $5,000 up to $75,000. The statute also sets a civil penalty for failing to notify or damaging a line. Not covered: routine farm and ranch work; landscape maintenance that disturbs no more than 12 inches by hand or 4 inches by machine. A homeowner on their own lot is exempt from the penalties, not from calling.", "source": "Colorado 811 Excavator Handbook (last update Nov 2022) pp. 5-23, 27-45; C.R.S. 9-1.5-103", "url": "https://a-us.storyblok.com/f/1021538/x/160e66dfe5/excavator-handbook.pdf", "checked": "2026-11-20", "edition": "Handbook last updated November 2022", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-ut-tickets-1", "state": "UT", "tier": "core", "title": "Utah 811: ticket life 21 days, updates, no-response notice", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Utah ticket life (54-8a-4(6)): a notice is \"valid for 21 days from the day on which the notice is given,\" and marks are good for no more than 21 calendar days (54-8a-5(3)). If digging will go past that, give a renewal notice at least 48 hours but no more than 7 calendar days before the ticket expires. Blue Stakes ticket types: New, Update (UPDT), No Response Notice (NRSP), Re-Mark (RMRK), Retransmit (RXMT), Cancel (CNCL). Its ticket field guide says the old ticket number is the \"Same number if a New ticket; different if Updated,\" and each ticket prints an \"Update By\" date and time. Send the update by that time. Operators answer through Blue Stakes' electronic positive response system. If an operator has not marked or answered within 48 hours, you may not dig where you know or can see there is an unmarked line until you have filed a no response notice and the operator has arranged to mark. The operator must mark \"within four business hours of the association receiving a no response notice.\" Very large jobs: an operator that can't mark an extensive excavation in time may \"request a meeting at the proposed excavation site.\" Colors follow the Common Ground Alliance Uniform Color Code.", "source": "Utah Code 54-8a-4, 54-8a-5 (2024); Blue Stakes of Utah \"Ticket Field Explanation\"", "url": "https://le.utah.gov/xcode/Title54/Chapter8A/C54-8a_1800010118000101.pdf", "checked": "2026-11-20", "edition": "Utah Code as amended by the 2024 General Session (ch. 369)", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ut-marks-1", "state": "UT", "tier": "core", "title": "Utah 811: tolerance zone 24 inches, hand tools first", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Utah tolerance zone (54-8a-2): when the size of the line is not marked, \"24 inches on either side of the outside edge of the mark.\" When the diameter is marked, half the marked diameter plus 24 inches on each side of the center. Hand tools first (54-8a-5.5): an excavator may not use \"any power-operated or power-driven excavating or boring equipment within the tolerance zone\" unless the exact location of the line has first been determined with hand tools. The operator can waive that, but only in writing or electronically. The statute has no white-lining requirement; Blue Stakes asks for white marks when the dig area is hard to describe. Marks follow the Common Ground Alliance Uniform Color Code and Marking Guidelines (the same colors as APWA). Gardening and tilling private ground do not need a ticket (54-8a-4(1)(b)).", "source": "Utah Code 54-8a-2, -4, -5, -5.5, -7, -8, -12 (as amended by 2024 ch. 369)", "url": "https://le.utah.gov/xcode/Title54/Chapter8A/C54-8a_1800010118000101.pdf", "checked": "2026-11-20", "edition": "Utah Code as amended by the 2024 General Session (ch. 369)", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ut-damage-1", "state": "UT", "tier": "core", "title": "Utah 811: line hits, emergencies, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "Utah, line hit (54-8a-7): give notice \"immediately to the operator.\" If the damage lets out electricity or gas or puts life in danger, immediately notify \"emergency responders, including 911 services.\" Do not backfill around the damaged line until the operator authorizes it. Emergency (54-8a-2, -4): \"an occurrence or suspected natural gas leak necessitating immediate action\" to prevent loss or damage. The advance notice rule does not apply during an emergency, and the fine section does not apply if reasonable precautions are taken. Fines (54-8a-8): \"no greater than $5,000 for each violation,\" capped at $100,000 for one excavation, plus up to $500 more for not giving notice at all. You also owe the repair cost. The attorney general can bring the case; if not, the operator or excavator can. Fines do not apply to digging with hand tools on property you own or occupy. Disputes over damage can go to the Underground Facilities Damage Dispute Board.", "source": "Utah Code 54-8a-2, -4, -5, -5.5, -7, -8, -12 (as amended by 2024 ch. 369)", "url": "https://le.utah.gov/xcode/Title54/Chapter8A/C54-8a_1800010118000101.pdf", "checked": "2026-11-20", "edition": "Utah Code as amended by the 2024 General Session (ch. 369)", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ga-marks-1", "state": "GA", "tier": "core", "title": "Georgia 811: tolerance zone 18 inches, reasonable care, white lining, sewer laterals", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Georgia tolerance zone (25-9-3): \"the width of the underground facility or sewer lateral plus 18 inches on either side of the outside edge.\" Inside it (25-9-8): you \"shall exercise reasonable care for the protection of the underground facility or sewer lateral.\" The law lists \"hand digging, pot holing, soft digging, vacuum excavation methods, pneumatic hand tools.\" Other mechanical methods \"may be used with the approval of the facility owner or operator.\" White lining (25-9-6(b)): when the site can't be described well enough, mark the route in white paint, flags or stakes (or electronically), or set an on-site meeting and tell Georgia 811. Owners mark with the APWA color code. Sewer laterals: the sewer owner helps designate laterals up to the edge of the public right of way. If a lateral can't be located, a green triangle is placed at the main pointing toward the property. Business hours are 7:00 AM to 4:30 PM on business days.", "source": "O.C.G.A. 25-9-3, 25-9-4, 25-9-6, 25-9-7, 25-9-8, 25-9-12, 25-9-14 (as printed by Georgia 811, eff. Sept 1, 2022)", "url": "https://georgia811.com/wp-content/uploads/2025/03/Georgia-Dig-Law_090122.pdf", "checked": "2026-11-20", "effective": "2022-09-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ga-damage-1", "state": "GA", "tier": "core", "title": "Georgia 811: line hits, emergencies, fines, what is not excavating", "topic": "811 emergencies and what to do when a line is hit", "text": "Georgia, line hit (25-9-8(e)-(f)): you \"shall immediately cease such blasting or excavating and notify the UPC and the appropriate facility owner or operator\" (the UPC is Georgia 811). Striking a gas or hazardous liquid line: you \"shall make an emergency 9-1-1 call.\" Emergency (25-9-3, 25-9-12): \"a sudden or unforeseen occurrence involving a clear and imminent danger to life, health, or property.\" The notice wait does not apply, but notify Georgia 811 \"as soon as practical.\" Extraordinary circumstances such as hurricanes, floods, ice and snow let owners post a later marking date in PRIS. Fines (25-9-14): the Public Service Commission may set a civil penalty \"not exceeding $10,000.00 for each violation.\" Dig without a ticket and cause damage and you are strictly liable for the repair. Not \"excavating\": farm tilling; pavement milling or repair no deeper than the pavement or 12 inches; road maintenance no deeper than 18 inches. Careful hand-tool (\"minimally intrusive\") digging used alone needs no notice.", "source": "O.C.G.A. 25-9-3, 25-9-4, 25-9-6, 25-9-7, 25-9-8, 25-9-12, 25-9-14 (as printed by Georgia 811, eff. Sept 1, 2022)", "url": "https://georgia811.com/wp-content/uploads/2025/03/Georgia-Dig-Law_090122.pdf", "checked": "2026-11-20", "effective": "2022-09-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-nc-marks-1", "state": "NC", "tier": "core", "title": "North Carolina 811: tolerance zone 24 inches, no machines until the line is seen", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "North Carolina tolerance zone (87-117): if the line's diameter is known, half the diameter plus 24 inches on each side of the centerline; if not, 24 inches on each side of the outside edge of the mark; 15 feet each side for underwater lines. This applies to every marked line, not only transmission lines. Inside the marked zone (87-122(c)): no mechanized equipment \"except noninvasive equipment\" made to protect the line, until the line has been seen or shown not to be there down to the depth of the dig. Machines may break and remove pavement only, to the depth of the pavement. Digging alongside a line: expose it at intervals of no more than 50 feet. Within 24 inches of oil, petroleum, gas transmission or electric transmission lines: only non-mechanized tools, unless the operator agrees in writing and has someone on site. Premarking: when the dig area can't be clearly identified, \"Premarking shall be made with soluble white paint, white flags, or white stakes.\" Operators mark with the APWA Uniform Color Code.", "source": "N.C.G.S. 87-117, 87-120 to 87-127, 87-129 (Article 8A, as amended by S.L. 2025-21)", "url": "https://www.ncleg.net/EnactedLegislation/Statutes/HTML/ByArticle/Chapter_87/Article_8A.html", "checked": "2026-11-20", "edition": "Statute as amended by Session Law 2025-21", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-nc-damage-1", "state": "NC", "tier": "core", "title": "North Carolina 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "North Carolina, line hit (87-126): immediately notify the Notification Center (NC811) and the operator if known, give the operator reasonable time to repair, and do not backfill until authorized. If the damage lets out electricity or gas or endangers life or property, you \"shall immediately notify emergency responders, including 911 services,\" then NC811 and the operator. Emergency (87-117, 87-125): \"An event involving a clear and imminent danger to life, health, or property.\" No advance notice, but notify NC811 as soon as practicable. Operators make first contact within 3 hours. Calling something an emergency does not remove liability, and a false emergency is a Class 3 misdemeanor. Penalties (87-129): the Underground Damage Prevention Review Board reviews reports and can recommend training, education and \"a civil penalty not to exceed two thousand five hundred dollars ($2,500)\"; the Utilities Commission issues the order. No notice needed (87-124): a single-family homeowner on their own land outside any utility right-of-way; tilling less than 12 inches deep; farm digging on land with no right-of-way; hand-tool locating or probing; pavement milling.", "source": "N.C.G.S. 87-117, 87-120 to 87-127, 87-129 (Article 8A, as amended by S.L. 2025-21)", "url": "https://www.ncleg.net/EnactedLegislation/Statutes/HTML/ByArticle/Chapter_87/Article_8A.html", "checked": "2026-11-20", "edition": "Statute as amended by Session Law 2025-21", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ny-tickets-1", "state": "NY", "tier": "core", "title": "New York 811: no ticket expiry, postponements, cancellations, conferences", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "New York notice rules (753-3.1): call \"at least two but not more than ten working days, not including the date of the call,\" before the start date. The rules set no ticket life. Postponed ten working days or less: \"no call to the one-call notification system or operators is required.\" Postponed more than ten working days: a new notice is needed. Cancelled job: you \"shall promptly communicate the cancellation\" to the operators through the one-call system. Demolition: ask for a pre-demolition conference at least seven working days ahead; operators must attend when asked. Start of work (753-3.3): only after you have \"received notification from each and every operator\" that there are no lines or that they are staked and marked. Where it exists you \"shall utilize the Automated Positive Response (APR) system.\" Design requests are separate and \"shall not be a substitute for the notice of intent to perform excavation or demolition.\" You must protect and keep the marks until they are no longer needed, and make sure your workers know Part 753 (753-3.15).", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; booklet updated May 9, 2025", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ny-damage-1", "state": "NY", "tier": "core", "title": "New York 811: line hits, emergencies, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "New York, line hit or contact (753-3.10): you \"shall immediately notify the operator of the facility.\" Stop digging near it until the operator has repaired it and says you can go on. Do not backfill near the damage until the operator has inspected and repaired it. Gas, liquid or electrical emergency (753-3.14): get everyone out and \"Immediately notify 911 and the operator of the affected facility.\" Emergency work (753-1.2, 753-3.1): \"Any abnormal condition which presents an immediate danger to life or property.\" You may start without advance notice but must notify the one-call system \"as soon as possible,\" and \"Extreme caution shall be employed.\" Fines (General Business Law 765): \"up to four thousand three hundred seventy-five dollars for the first violation\" and \"up to an additional seventeen thousand five hundred dollars for each succeeding violation\" within twelve months. The fine does not apply to an excavator who damages a line because the operator failed to follow the rules. Farm tilling is not \"excavation\" under Part 753.", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; GBL 765 as of May 9, 2025", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-il-tickets-1", "state": "IL", "tier": "core", "title": "Illinois 811: notice good 25 days, extensions, joint meets, emergency requests", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Illinois notice life (220 ILCS 50/2, 4): a normal notice is \"valid for 25 days from the date of the initial request\" unless extended. An extension may be requested no earlier than the 20th day and adds 25 days. Extensions \"may not be made simply to keep a prior notice open\" when no digging is going on. Before asking for an extension you must pre-mark again (Sec. 4(g)). Positive response (Sec. 5.1, duties from January 1, 2026): operators post a response code by the dig start time; the excavator confirms all have answered. If one has not, the excavator \"may proceed after providing a no show or incomplete request through JULIE.\" Emergency request (Sec. 6): for \"imminent danger to life, health, or property or a utility service outage\" needing action within 2 days. There is \"a minimum wait time of 2 hours after an emergency request\" unless the danger won't allow it; operators answer within 2 hours. An emergency notice expires 10 days after it is made. Large projects and joint meets (Sec. 5.3): give at least 2 days' notice of a joint meet (5 days for large projects) and not more than 60 days before the planned start. Planning design requests (Sec. 5.2): operators answer within 10 days.", "source": "220 ILCS 50/2, 4, 5.1, 5.2, 5.3, 6, 7, 10, 11 (as amended by P.A. 103-614, eff. Jan 1, 2025)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "effective": "2025-01-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-il-marks-1", "state": "IL", "tier": "core", "title": "Illinois 811: tolerance zone 18 inches, hand or vacuum digging, colors, black on snow", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Illinois tolerance zone (220 ILCS 50/2): where the size of the line is not shown, \"one and one-half feet on either side of the outside edge\" of the marking; where the diameter is shown, half the diameter plus one and one-half feet on each side. Inside it (Sec. 4): plan the dig to keep away from lines, use \"hand or vacuum excavation methods to the depth of the proposed excavation,\" and keep watching the excavation by eye until you are clear of the marked line. Pre-marking is required (Sec. 4(c)); \"Electronic white lining may be used when available.\" Colors (Sec. 10): proposed excavation \"Safety White (Black when snow is on the ground)\"; electric red; gas and oil yellow; communications orange; water blue; sewer green; non-potable water and slurry purple; temporary survey pink. Sewer owners must mark their lines when the dig will go deeper than 7 feet (Sec. 10(b)). Removing or wrecking marks on purpose can be fined up to $1,000.", "source": "220 ILCS 50/2, 4, 5.1, 5.2, 5.3, 6, 7, 10, 11 (as amended by P.A. 103-614, eff. Jan 1, 2025)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "effective": "2025-01-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-il-damage-1", "state": "IL", "tier": "core", "title": "Illinois 811: line hits, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Illinois, line hit (220 ILCS 50/7): \"immediately notify the affected underground utility facility owner or operator and JULIE,\" and stop digging near the damage if it threatens life or property. Do not repair, clamp or pinch the line unless the owner tells you to. If gas or other hazardous material is escaping, \"the excavator responsible for the excavation or demolition shall call 9-1-1.\" Fines (Sec. 11), set by the Illinois Commerce Commission: up to $5,000 per offense for willfully digging without the required notice; up to $2,500 for other willful violations; up to $1,000 for removing marks. A homeowner who breaks the Act on their own residential property is not fined but still owes for the damage (Sec. 8(d)). Not \"excavation\": farm tillage, railroad right-of-way maintenance, surveying without power equipment, roadway surface milling. The Act lets a home rule city of over 1,000,000 people (Chicago) run its own damage prevention program.", "source": "220 ILCS 50/2, 4, 5.1, 5.2, 5.3, 6, 7, 10, 11 (as amended by P.A. 103-614, eff. Jan 1, 2025)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "effective": "2025-01-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-oh-tickets-1", "state": "OH", "tier": "core", "title": "Ohio 811: no expiry date, remarks, ticket types, phased projects", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Ohio tickets (OHIO811 manual, June 2026): the notice window is 2 working days to 16 calendar days before you start. No ticket life or expiry is given in the manual or in O.R.C. 3781.28 as amended June 9, 2026. An Ohio 811 FAQ page on ticket expiry exists but could not be opened, so expiry is not confirmed either way: ask OHIO811 on long jobs. Remark: when marks are destroyed or removed, contact OHIO811 and \"Wait two working days, not including the day of the notification, for the excavation site to be remarked.\" Do not repaint the locator's marks yourself. Ticket types named: routine; emergency (by phone only, any hour); design request; Complex Project; and a LATE notice the system sends an owner that missed the deadline. Large, phased jobs: give the owners written notice of the excavation with projected timelines so marking can be staged. If an owner wants to be present, give at least one full working day's notice before digging near its line. Positive Response is strongly advised before every start; the manual says not to assume all owners have answered.", "source": "OHIO811 Excavator Manual (rev. June 2026) pp. 5-7, 10-17, 20-24, 40; O.R.C. 3781.25 to 3781.32", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "checked": "2026-11-20", "edition": "Manual revised June 2026", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "whether an Ohio ticket expires"}},
{"lib": "field", "chunk": {"id": "dig-oh-marks-1", "state": "OH", "tier": "core", "title": "Ohio 811: tolerance zone 18 inches, spotter, premarking, colors", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Ohio tolerance zone: the width of the underground line \"plus eighteen inches on each side of the facility\" (manual p. 16; O.R.C. 3781.25). Inside it you must work \"in a careful, prudent\" and nondestructive way: hand digging, pot holing or vacuum excavation. When a machine is used near the zone, have a second person, not the equipment operator, watch the dig, and keep reasonable clearance between the line and the cutting edge. Premarking in white paint is required unless one of four exceptions applies. For one spot, mark it with white dashes; for a trench, mark the center line with white dashes. White flags or stakes may be used instead. Colors: white proposed excavation; pink survey; red electric; yellow gas, oil, steam; orange communication; blue potable water; purple reclaimed water and irrigation; green sewers and drains.", "source": "OHIO811 Excavator Manual (rev. June 2026) pp. 5-7, 10-17, 20-24, 40; O.R.C. 3781.25 to 3781.32", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "checked": "2026-11-20", "edition": "Manual revised June 2026", "confidence": "high", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-oh-damage-1", "state": "OH", "tier": "core", "title": "Ohio 811: line hits, emergencies, exemptions, complaints", "topic": "811 emergencies and what to do when a line is hit", "text": "Ohio, line hit (manual p. 17): first get everyone to safety, stop work and protect the area. Do not try to repair the line or stop a leak. Notify the utility and OHIO811 as soon as the damage is found, and give the utility reasonable time to repair. If flammable, corrosive, explosive or toxic material is escaping, call 9-1-1. Tell them the location, the kind of line and the depth. Emergency: \"a sudden or unexpected occurrence involving a clear and imminent danger.\" Emergency notices are by phone only, and only for real emergencies. Not excavation: farm tilling no deeper than 12 inches; grass seeding tilling to 4 inches; hand-tool work within 12 inches of an exposed utility fitting. Violations: anyone can file a complaint with the Underground Technical Committee at puco.ohio.gov; the manual warns of \"fines or penalties, even if a damage has not occurred.\" Fine amounts were not confirmed in this pass.", "source": "OHIO811 Excavator Manual (rev. June 2026) pp. 5-7, 10-17, 20-24, 40; O.R.C. 3781.25 to 3781.32", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "checked": "2026-11-20", "edition": "Manual revised June 2026", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "fine amounts (O.R.C. 3781.34 to 3781.36)"}},
{"lib": "field", "chunk": {"id": "dig-mi-tickets-1", "state": "MI", "tier": "core", "title": "Michigan 811: ticket life 21 or 180 days, no renewals, additional assistance", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Michigan ticket life (MCL 460.725): a ticket is \"valid for 21 days from the start date,\" or 180 days if the dig notice says the work will not be done in 21 days. MISS DIG says digging must start within 14 days and be done within 21 days of the Work Legal Start Date, and \"If the work has not started within 14 days or is not completed within 21 days, a new ticket is required.\" There is no renew button: a Retransmit keeps the number but does not add time. For long jobs ask for a Normal 180-Day or Project 180-Day ticket. Marks destroyed or covered: give notice; the owner re-marks \"within 24 hours, excluding all hours on nonbusiness days.\" Can't find a marked line inside its approximate location: ask for additional assistance; the owner must respond \"within 3 hours\" in business hours (7 AM to 5 PM Eastern, business days). Reason to think there is an unmarked line, including \"Lack of a positive response to a ticket\": \"stop excavation in the immediate vicinity\" and give immediate additional notice. Design ticket (460.726a): information only, \"not marking\"; it does not replace a dig notice.", "source": "MCL 460.723, 460.725, 460.726a, 460.727, 460.731, 460.732 (2013 PA 174; compilation through PA 91 of 2026); MISS DIG 811 FAQ and Ticket Types sheet (July 2024)", "url": "https://www.legislature.mi.gov/documents/mcl/archive/2026/September/mcl-Act-174-of-2013.pdf", "checked": "2026-11-20", "edition": "MCL compilation complete through PA 91 of 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-mi-marks-1", "state": "MI", "tier": "core", "title": "Michigan 811: caution zone 48 inches, soft excavation, white lining", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Michigan caution zone (MCL 460.723): \"the area within 48 inches of either side of the facility marks.\" The marks themselves show an approximate location: a strip at least 36 inches wide, or the marked width of the line plus 18 inches on each side. Before digging in the caution zone (460.725): \"expose all marked facilities in the caution zone by soft excavation.\" Soft excavation means hand digging or vacuum-type methods. Power tools may be used there \"only after the facilities are exposed or the precise location of the facilities is established.\" Support and brace exposed lines. White lining: where the site can't be described well enough, mark the work area \"with white paint or flags, or both\" before you send the ticket. Colors: white proposed excavation; pink survey; red electric; yellow gas, oil, steam, petroleum; orange communication; blue potable water; purple reclaimed water and irrigation; green sewers and drains.", "source": "MCL 460.723, 460.725, 460.726a, 460.727, 460.731, 460.732 (2013 PA 174; compilation through PA 91 of 2026)", "url": "https://www.legislature.mi.gov/documents/mcl/archive/2026/September/mcl-Act-174-of-2013.pdf", "checked": "2026-11-20", "edition": "MCL compilation complete through PA 91 of 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-mi-damage-1", "state": "MI", "tier": "core", "title": "Michigan 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Michigan, line hit (MCL 460.725): \"If an excavator contacts or damages a facility, the excavator shall provide immediate notice to the facility owner or facility operator.\" If flammable, toxic or corrosive gas or liquid escapes, or life is in danger, \"call 9-1-1\" and take reasonable steps to protect people. Emergency: \"a sudden or unforeseen occurrence\" with \"clear and imminent danger to life, health, or property.\" Give prompt emergency notice and do only what the emergency reasonably requires. Owners respond to emergency notices within 3 hours. Penalties (460.731, 460.732): knowingly damaging a line and not reporting it, or hiding it by backfilling, is a misdemeanor: up to 1 year or a fine up to $5,000. The Public Service Commission can order civil fines up to $5,000 per violation; each day counts separately. Not excavation: farm work no deeper than 12 inches in a public right-of-way, or 18 inches within 25 yards of a petroleum or natural gas pipeline outside it; replacing a fence post or sign post in place; routine road maintenance to 12 inches.", "source": "MCL 460.723, 460.725, 460.726a, 460.727, 460.731, 460.732 (2013 PA 174; compilation through PA 91 of 2026)", "url": "https://www.legislature.mi.gov/documents/mcl/archive/2026/September/mcl-Act-174-of-2013.pdf", "checked": "2026-11-20", "edition": "MCL compilation complete through PA 91 of 2026", "confidence": "medium", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-pa-marks-1", "state": "PA", "tier": "core", "title": "Pennsylvania 811: tolerance zone 18 inches, prudent techniques, white", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Pennsylvania tolerance zone (73 P.S. 176): \"the horizontal space within eighteen inches of the outside wall or edge of a line or facility.\" Inside it (73 P.S. 180(4)): \"Within the tolerance zone the excavator shall employ prudent techniques, which may include hand-dug test holes,\" vacuum excavation or similar devices, to find the exact position of the line. White (clause 11): use \"the color white to mark a proposed excavation work site when exact work site information cannot be provided.\" Trenchless work (boring, directional drilling): follow the Common Ground Alliance best practices (clause 11.2). What is not \"excavation work\": soft excavation by vacuum, air or water; farm tilling to a depth of less than eighteen inches; minor routine road maintenance less than eighteen inches deep; work up to twenty-four inches below the surface inside a State highway right-of-way.", "source": "73 P.S. 176, 180, 182.10 (Underground Utility Line Protection Law; FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-176/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-pa-damage-1", "state": "PA", "tier": "core", "title": "Pennsylvania 811: line hits, emergencies, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "Pennsylvania, line hit (73 P.S. 180(7)-(8), (16)): report any break, leak or damage to the facility owner immediately. If the damage lets flammable, toxic or corrosive gas or liquid escape, immediately notify 911 and the facility owner, take reasonable steps to protect people, and stay on site to tell the responders what happened. File an alleged violation report through PA One Call \"not more than thirty days after striking or damaging a facility owner's line.\" Emergency: \"a sudden or unforeseen occurrence involving a clear and immediate danger to life, property or the environment,\" including serious breaks in an owner's lines. The 3 to 10 day notice does not apply, but all facility owners must be notified \"as soon as possible before, during or after.\" Penalties (73 P.S. 182.10): the Public Utility Commission may issue a warning or an administrative penalty of up to $2,500 per violation, and up to $50,000 if the violation causes injury, death or property damage of $25,000 or more. Unpaid penalties or a skipped education program add $100 a day up to $5,000.", "source": "73 P.S. 176, 180, 182.10 (Underground Utility Line Protection Law; FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-182-10/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-de-marks-1", "state": "DE", "tier": "core", "title": "Delaware 811: tolerance zone 24 inches, no machines, unmarked lines", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Delaware tolerance zone (26 Del. C. 802): \"the horizontal space within 24 inches of the outside wall or edge of a facility.\" \"No mechanized equipment will be allowed within the tolerance zone,\" except to remove pavement or other hard surface under set conditions. \"Vacuum excavation will be permitted within the tolerance zone.\" Excavator duties (806): protect the lines, which \"shall include but may not be limited to hand digging\"; \"The excavator shall employ prudent techniques, which may include test holes.\" See a line that was not marked (a valve box, meter, pedestal): call it in; the operator \"will have a maximum of 2 hours to respond.\" Operators answer tickets within 3 business days and mark with the current APWA colors. Design tickets and meeting tickets (for complex projects) do not allow digging. A business day is any day but Saturday, Sunday or a legal holiday.", "source": "26 Del. C. 802, 803, 805, 806, 808, 810 (Underground Utility Damage Prevention and Safety Act; through 85 Del. Laws c. 345)", "url": "https://delcode.delaware.gov/title26/c008/sc01/index.html", "checked": "2026-11-20", "edition": "Delaware Code online, through 85 Del. Laws c. 345", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-de-damage-1", "state": "DE", "tier": "core", "title": "Delaware 811: line hits, emergencies, fines, exemptions", "topic": "811 emergencies and what to do when a line is hit", "text": "Delaware, line hit (26 Del. C. 806): \"Report immediately to the facility owner or facility operator\" any break or leak. \"Immediately notify 911 and the facility owner or facility operator if damage\" lets dangerous gas or liquid escape. Emergency (802, 806(b)): \"a sudden or unforeseen occurrence involving a clear or imminent danger to life, health, or property.\" Emergency digging skips most of the advance steps, but notify the center \"at the earliest practicable moment.\" Fines (810): first offense $100 to $1,000; later offenses $200 to $5,000 per violation. Top amounts: $1,000,000 for a violation that causes a death, $500,000 for damage to a structure, $100,000 for other violations. The Attorney General can take the death and structure cases; the Public Service Commission handles the rest. Exempt (808): digging by the owner of a private residence on their own land (still liable for damage); surface cultivation such as tilling outside rights-of-way and easements. Patch paving up to 12 inches deep and hand-driven non-metal stakes 6 inches or less are not excavation.", "source": "26 Del. C. 802, 803, 805, 806, 808, 810 (Underground Utility Damage Prevention and Safety Act; through 85 Del. Laws c. 345)", "url": "https://delcode.delaware.gov/title26/c008/sc01/index.html", "checked": "2026-11-20", "edition": "Delaware Code online, through 85 Del. Laws c. 345", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-dc-damage-1", "state": "DC", "tier": "core", "title": "District of Columbia 811: hand digging, line hits, emergencies, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "District of Columbia rules near marked lines (D.C. Code 34-2704): operators mark \"to within 2 feet from the outermost part of the underground facility.\" Once the dig comes into the immediate vicinity, within 18 inches of the outermost part of the line, protect it and \"expose the underground facility by hand digging.\" Line hit (34-2705, 34-2706): notify the operator immediately and allow reasonable time for repair before working near it. If flammable, toxic or corrosive gas or liquid is released, also notify 911. Do not backfill a damaged line without the operator's permission. Emergency (34-2709): for \"imminent danger to life, health, or property\" the advance notice is not required if reasonable precautions are taken; notify the operators directly and as soon as possible. Operators mark within 2 hours where practicable. Fines (34-2707): $2,500 for a first violation, $5,000 for a second, $10,000 for a third or later, brought by the Attorney General. Damage a line without following the notice rules and you owe three times the repair cost. Routine maintenance such as patch paving inside the old excavation limits and no deeper than 12 inches below the prior grade needs no notice.", "source": "D.C. Code 34-2704 to 34-2709 (through D.C. Law 23-186, Mar. 16, 2021)", "url": "https://code.dccouncil.gov/us/dc/council/code/titles/34/chapters/27/index.full.html", "checked": "2026-11-20", "edition": "D.C. Code online, through D.C. Law 23-186 (2021)", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-va-tickets-1", "state": "VA", "tier": "core", "title": "Virginia 811: 48-hour wait, 15 working days, updates get a new number, 3-hour rule", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Virginia timing (Va. Code 56-265.17): no digging until you have confirmed that \"each operator has marked its utility lines,\" has none, or has posted a positive response that lets you proceed. If an operator has not responded, the notification center re-notifies it. See clear evidence of an unmarked line after the 48 hours (counted from 7:00 a.m. the next working day): contact Virginia 811 again and wait; the operator \"shall respond within three hours.\" Life: the notice is \"valid for 15 working days.\" Ask for the re-mark three working days before the end or when marks are illegible; the operator re-marks within 48 hours and the re-mark is good for another 15 working days. Virginia 811's ticket sheet: \"An Update or Re-mark will produce a new request number for the area of excavation\"; \"An Update locate request should be requested on the third working day before the end of the fifteen-day period.\" A meeting request is not a ticket to dig on. Designers have their own notice rule (56-265.17:1). In an emergency the waiting rules do not apply.", "source": "Va. Code 56-265.17 (2023 amendments); Virginia 811 \"Ticket Types\" sheet (May 15, 2026)", "url": "https://law.lis.virginia.gov/vacode/56-265.17/", "checked": "2026-11-20", "edition": "Section as amended in 2023 (chs. 299 and 300)", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-nj-damage-1", "state": "NJ", "tier": "core", "title": "New Jersey 811: line hits, emergencies, fines", "topic": "811 emergencies and what to do when a line is hit", "text": "New Jersey, line hit (N.J.A.C. 14:2-3.6): for a gas, liquid petroleum or other hazardous liquid line, \"immediately call 911.\" Then report the damage to the operator; if you can't reach the operator, \"report the damage to the One-Call center at 811 or 1-800-272-1000.\" Protect the markout until it \"is no longer necessary\" (14:2-3.3). Emergency notices are good only while the emergency lasts (14:2-3.5). Operators must act within one hour of learning of an emergency. Operators that fail to mark are liable for the excavator's costs, labor, parts, equipment and downtime (14:2-4.2). Fines (14:2-6.2): \"not less than $ 1,000 and not more than $ 2,500 per day for each day the violation continues,\" and \"shall not exceed $ 25,000 for any related series of violations.\" The Board of Public Utilities enforces. Routine residential yard and right-of-way maintenance with non-mechanized tools is not \"excavation.\" Colors follow ANSI Z535.1. This is the Board's 2021 readoption text; later changes were not confirmed.", "source": "N.J.A.C. 14:2-3.1, 3.2, 3.5, 3.6, 4.2, 4.4, 5.2, 6.2 (BPU One-Call rules, 2021 readoption text)", "url": "https://nj.gov/bpu/pdf/rules/Chapter%202%20One%20Call%20Rules%2010.28.21%20Clean%20Version.pdf", "checked": "2026-11-20", "edition": "BPU rule text dated Oct 28, 2021 (readoption proposal)", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "this is the 2021 proposal text, not the current code"}},
{"lib": "field", "chunk": {"id": "dig-ma-damage-1", "state": "MA", "tier": "core", "title": "Massachusetts 811: line hits, emergencies, fines, exemptions (Dig Safe)", "topic": "811 emergencies and what to do when a line is hit", "text": "Massachusetts, line hit (Dig Safe manual p. 19): \"you must immediately call the operator whose facilities have been damaged,\" even for a scrape to the coating. Gas release: call 911. Electric contact: call the electric operator and the fire department. Not sure whose line it is: call 811. Leave the damaged line exposed. Emergency: \"An emergency is a sudden or unexpected occurrence.\" Do not ask for an Emergency ticket for a job that is not one. Emergency notice must be given the same day. Unmarked structure, or something that does not look right: tell Dig Safe before digging there. Marks destroyed before the work is done: call for a re-mark. Fines in Massachusetts (manual p. 27 table): $1,000 for a first offense and $5,000 to $10,000 after that. Enforced by the Department of Public Utilities. Not excavation in Massachusetts: hand-tool gardening and quarry blasting. On snow, Dig Safe recommends fluorescent pink for pre-marking so it can be seen.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-nh-damage-1", "state": "NH", "tier": "core", "title": "New Hampshire 811: line hits, emergencies, fines, exemptions (Dig Safe)", "topic": "811 emergencies and what to do when a line is hit", "text": "New Hampshire, line hit (Dig Safe manual p. 19): \"you must immediately call the operator whose facilities have been damaged,\" even for a scrape to the coating. Gas release: call 911. Electric contact: call the electric operator and the fire department. Not sure whose line it is: call 811. Leave the damaged line exposed. Emergency: \"An emergency is a sudden or unexpected occurrence.\" Do not ask for an Emergency ticket for a job that is not one. Emergency notice must be given the same day. Unmarked structure, or something that does not look right: tell Dig Safe before digging there. Marks destroyed before the work is done: call for a re-mark. Fines in New Hampshire (manual p. 27 table): $500 for a first offense and up to $5,000 after that. Enforced by the Department of Energy. Not excavation in New Hampshire: farm tilling and yard work on residential property with non-mechanized tools. On snow, Dig Safe recommends fluorescent pink for pre-marking so it can be seen.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-vt-damage-1", "state": "VT", "tier": "core", "title": "Vermont 811: line hits, emergencies, fines, exemptions (Dig Safe)", "topic": "811 emergencies and what to do when a line is hit", "text": "Vermont, line hit (Dig Safe manual p. 19): \"you must immediately call the operator whose facilities have been damaged,\" even for a scrape to the coating. Gas release: call 911. Electric contact: call the electric operator and the fire department. Not sure whose line it is: call 811. Leave the damaged line exposed. Emergency: \"An emergency is a sudden or unexpected occurrence.\" Do not ask for an Emergency ticket for a job that is not one. Emergency notice must be given the same day. Unmarked structure, or something that does not look right: tell Dig Safe before digging there. Marks destroyed before the work is done: call for a re-mark. Fines in Vermont (manual p. 27 table): up to $500 for a first offense and up to $5,000 after that. Enforced by the Department of Public Service. Not excavation in Vermont: farm tilling, routine home gardening with hand tools outside easements, and routine public highway maintenance. On snow, Dig Safe recommends fluorescent pink for pre-marking so it can be seen.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-ri-damage-1", "state": "RI", "tier": "core", "title": "Rhode Island 811: line hits, emergencies, fines, exemptions (Dig Safe)", "topic": "811 emergencies and what to do when a line is hit", "text": "Rhode Island, line hit (Dig Safe manual p. 19): \"you must immediately call the operator whose facilities have been damaged,\" even for a scrape to the coating. Gas release: call 911. Electric contact: call the electric operator and the fire department. Not sure whose line it is: call 811. Leave the damaged line exposed. Emergency: \"An emergency is a sudden or unexpected occurrence.\" Do not ask for an Emergency ticket for a job that is not one. Emergency notice must be given the same day. Unmarked structure, or something that does not look right: tell Dig Safe before digging there. Marks destroyed before the work is done: call for a re-mark. Fines in Rhode Island (manual p. 27 table): $350 for a first offense and $2,500 after that. Enforced by the Division of Public Utilities and Carriers. Not excavation in Rhode Island: moving earth with hand or animal-powered tools, and farm tilling. On snow, Dig Safe recommends fluorescent pink for pre-marking so it can be seen.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-me-damage-1", "state": "ME", "tier": "core", "title": "Maine 811: line hits, emergencies, fines, exemptions (Dig Safe)", "topic": "811 emergencies and what to do when a line is hit", "text": "Maine, line hit (Dig Safe manual p. 19): \"you must immediately call the operator whose facilities have been damaged,\" even for a scrape to the coating. Gas release: call 911. Electric contact: call the electric operator and the fire department. Not sure whose line it is: call 811. Leave the damaged line exposed. Emergency: \"An emergency is a sudden or unexpected occurrence.\" Do not ask for an Emergency ticket for a job that is not one. Emergency notice must be given the same day. Unmarked structure, or something that does not look right: tell Dig Safe before digging there. Marks destroyed before the work is done: call for a re-mark. Fines in Maine (manual p. 27 table): up to $1,000, or up to $10,000 for a repeat within 12 months (23 M.R.S. 3360-A). Enforced by the Public Utilities Commission. Not excavation in Maine: tilling and gardening or farm earth work; the statute also has rules for timber harvesting, cemeteries, shoulder grading, quarries and private road grading no deeper than 6 inches. On snow, Dig Safe recommends fluorescent pink for pre-marking so it can be seen.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-me-marks-1", "state": "ME", "tier": "core", "title": "Maine 811: statute: 3 business days, 60 days, 18 inches, non-members", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Maine statute (23 M.R.S. 3360-A): notify the damage prevention system \"at least 3 business days but not more than 30 calendar days prior to the commencement of excavation.\" Mark the proposed dig area before you call. If the work is not completed \"60 calendar days after notification,\" or it grows beyond the first location, notify again. 18-inch rule: an excavator \"may not use mechanical means of excavation when excavating within 18 inches of any marked underground facilities\" until the lines are exposed. Air vacuum methods are not \"mechanical means.\" Non-members: you must notify any owner that is not a Dig Safe member \"in writing or in person\" and wait until it marks or 3 business days pass, whichever is first. Emergency: take all reasonable steps to notify the system and mark the site, and start within 12 hours of the notice. Line hit: \"immediately notify the affected underground facility operator\"; no backfill without that operator's permission; natural gas or hazardous release, call 9-1-1. The Public Utilities Commission can fine up to $1,000 (up to $10,000 for a repeat within 12 months) and order training.", "source": "23 M.R.S. 3360-A (legislature.maine.gov)", "url": "https://legislature.maine.gov/statutes/23/title23sec3360-A.html", "checked": "2026-11-20", "edition": "Maine Revised Statutes online, read Nov 20, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-al-marks-1", "state": "AL", "tier": "core", "title": "Alabama 811: tolerance zone 18 inches from 2027, noninvasive digging, large projects", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "Alabama tolerance zone under the 2026 law (SB205, in force January 1, 2027): \"The width of the underground facility plus 18 inches on either side of the outside edge\" (37-15-2). The tolerance zone under the law in force before that date was not confirmed. Excavator duties (37-15-8): \"Determine the location of any marked underground facility utilizing noninvasive methods of excavation\" (hand digging, pot holing, soft digging, vacuum excavation); \"Maintain a clearance of at least 18 inches between any underground facility and the cutting edge\"; when crossing a line in the zone use reasonable care to find its depth. Find an unmarked line after notice: you \"shall not begin excavating until an additional notice is made.\" White is for the excavator's premarks only. Design or survey locate request: the operator answers within five working days; it can't be used to dig. Complex or large projects (planned past 40 working days, five or more crews at once, or many requests for one job): give notice at least five working days before a pre-excavation planning meeting and work to an agreed locate schedule. An operator may require this process.", "source": "Ala. Code 37-15-2, -4, -4.1, -4.2, -6, -8, -9, -10 as amended by 2026 SB205 (enrolled), effective Jan 1, 2027", "url": "https://alison.legislature.state.al.us/files/pdf/SearchableInstruments/2026RS/SB205-enr.pdf", "checked": "2026-11-20", "effective": "2027-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "tolerance zone before Jan 1, 2027"}},
{"lib": "field", "chunk": {"id": "dig-al-damage-1", "state": "AL", "tier": "core", "title": "Alabama 811: line hits, fines, exemptions (2027 law)", "topic": "811 emergencies and what to do when a line is hit", "text": "Alabama, line hit (37-15-9): notify the operator \"immediately upon discovery of such damage\" and allow reasonable time for repairs. If flammable, corrosive, explosive or toxic material is leaking, immediately report to the operator or the One-Call system and to law enforcement and the fire department (call 911). Emergency excavation: work \"required to eliminate an imminent danger to life, health, property, or the environment.\" No civil penalty for a violation during an emergency unless it was willful or malicious. Civil penalties (37-15-10, as amended effective January 1, 2027): first violation up to $500 per incident or training or both; second within 12 months up to $1,000; third within 12 months up to $3,000 plus training; gross negligence or willful noncompliance up to $10,000 per incident. Complaints must be made within 30 days of the known occurrence. No notice needed: plowing less than 12 inches deep for farming; digging on your own property or easement where no one else has lines. A property owner using hand tools on their own property is outside the hand digging rules.", "source": "Ala. Code 37-15-2, -4, -4.1, -4.2, -6, -8, -9, -10 as amended by 2026 SB205 (enrolled), effective Jan 1, 2027", "url": "https://alison.legislature.state.al.us/files/pdf/SearchableInstruments/2026RS/SB205-enr.pdf", "checked": "2026-11-20", "effective": "2027-01-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ky-damage-1", "state": "KY", "tier": "core", "title": "Kentucky 811: second notice, unmarked lines, line hits", "topic": "811 emergencies and what to do when a line is hit", "text": "Kentucky, when things go wrong (KRS 367.4911): an operator has not marked or answered by the end of the two working days: send a second notice to the center. No response within one working day after that second notice: an excavator who has complied in full is not liable for damage to the lines that would have been located, except for negligence or intentional misconduct, and except for certain gas and hazardous liquid pipelines. Find a line that was not marked: notify a notification center immediately; the operator has six business hours to identify it. Damage a line: \"cease excavation or demolition activities and notify all affected operators.\" If it creates a safety concern for the public or the crew, notify the public safety agencies. If flammable, toxic or corrosive gas or liquid escapes, stop work and call 911. Inside the tolerance zone \"hand-dig or use nonintrusive means to avoid damage to the underground facility.\" Penalty amounts are in KRS 367.4917 and were not confirmed in this pass; the Public Service Commission enforces for gas and hazardous liquid lines.", "source": "KRS 367.4911 (Justia copy, effective Jan 1, 2022)", "url": "https://law.justia.com/codes/kentucky/chapter-367/section-367-4911/", "checked": "2026-11-20", "effective": "2022-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "penalty amounts; tolerance zone width in inches"}},
{"lib": "field", "chunk": {"id": "dig-id-tickets-1", "state": "ID", "tier": "core", "title": "Idaho 811: ticket types, hand dig rule, emergencies, fines, exemptions", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Idaho ticket types (Guide to Safe Digging pp. 9-10): Emergency, Priority, Standard, Meet request (large project footprint: meet in two business days or as set, locates two business days after), Design request (maps in up to seven business days), Second request (marks missing), Update request (extends the expiry of an active ticket). Hand dig rule (Idaho Code 55-2207): \"Determine by hand digging, in the area twenty-four (24) inches or less from the facilities,\" the exact location. A vacuum pothole does not show fittings, so hand dig the rest of the zone too. Emergency: exempt from the notice time, but give notice at least two hours before starting where you can; owners try to reach you within one hour and arrive within two. Damaged lines must not be buried until repaired. Penalties: training for a first violation; up to $1,000 for a second and up to $5,000 for later ones within 18 months. A homeowner's first failure to call on their own lot may get a written warning. No ticket needed: digging less than 15 inches deep on private property outside recorded easements, and farm tilling under 15 inches.", "source": "Idaho Guide to Safe Digging 2026-27 (Damage Prevention Board, DOPL) pp. 4, 7, 9-12, 15-20, 29-36; Idaho Code 55-2201 to 55-2212", "url": "https://dopl.idaho.gov/wp-content/uploads/2026/04/DAM-ID-Guide-to-Safe-Digging-26_27.pdf", "checked": "2026-11-20", "edition": "2026-27 guide; statutes and rules in it current as of July 1, 2024", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ak-tickets-1", "state": "AK", "tier": "core", "title": "Alaska 811: ticket types, emergencies, exemptions", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Alaska ticket types (Alaska 811 handbook p. 6): Standard, Standard Remote, Emergency, and Design Planning. A design or planning request only gives you the owners' contacts; you then contact each owner yourself. A site meet can be asked for on a large or complicated project, and large jobs should be called in as a sequence of sections. Each phase of a new building is a separate request. A remark request is not the same as an update of the ticket. Emergency: a condition that is \"a clear and present danger to life, health, or property, or an unplanned service interruption.\" Emergency requests are handled at once; leave a callback number. In an emergency the excavator must notify each operator immediately (AS 42.30.400(c)). Calling in a false emergency can be penalized. Not excavation: \"tilling of the soil less than 12 inches in depth for agricultural purposes.\" An operator and an excavator may waive the notice and locate rules by written agreement for set areas and times. Members do not locate private lines, such as a line from a house to a garage. Alaska Digline does not enforce the law; a court sets the civil penalty.", "source": "Alaska 811 Excavator Handbook (2026) pp. 2-3, 6-8, 13-22; AS 42.30.400 to 42.30.490", "url": "https://cdn.pelicancorp.com/pdfs/26-ak811-excavator-handbook.pdf", "checked": "2026-11-20", "edition": "2026 handbook", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-mn-tickets-1", "state": "MN", "tier": "core", "title": "Minnesota 811: ticket types, updates, meet tickets, exemptions", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Minnesota ticket types (GSOC Handbook 2026 pp. 33-46): Normal; Emergency; Meet (required for a dig of one mile or more; the meet is at least 48 hours after you contact GSOC); Owner Inquiry, Planning (operators have 15 working days), Design/Pre-Con Meet and Boundary Survey, none of which allow digging; and Correction, Cancellation and Update. Updates: \"All Update tickets will have a new GSOC ticket number,\" with the old number shown for reference, and the handbook says \"Only one (1) remark/extend life of ticket is allowed per ticket.\" Meet tickets last 14 calendar days, or up to six months with a written schedule that lists the meet date, who came, a sketch, and the next meetings. Past six months, get a new ticket first. Emergency: \"a condition that poses a clear and immediate danger to life or health\" or a major loss of property. Scheduling problems and customer demands are not emergencies. Operators try to reach you within one hour and are on site within three when needed. No ticket needed: farm tilling or planting shallower than 18 inches; gardening shallower than 12 inches. Homeowners and farmers must call for anything else.", "source": "Gopher State One Call Handbook 2026 pp. 14-28, 33-46, 76, 84; Minn. Stat. ch. 216D", "url": "https://gopherstateonecall.org/wp-content/uploads/GSOCHandbook2026.pdf", "checked": "2026-11-20", "edition": "2026 Handbook", "confidence": "medium", "kind": "summary", "license": "summary"}},
{"lib": "field", "chunk": {"id": "dig-sc-tickets-1", "state": "SC", "tier": "core", "title": "South Carolina 811: ticket types, large projects, emergencies, complaints", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "South Carolina ticket types (SC811 Excavator Manual 2026): Normal; Design (operators have 15 full working days; no digging on it); Emergency; Large Project; Subaqueous (underwater: 10 working days' notice, tolerance zone 15 feet either side). Large Project: a job expected to take more than 90 days, or that meets the highway, development or utility size tests. Notify the center at least 30 days before starting; a planning meeting is held within 15 days; each phase gets its own start and end dates and needs no updates while work stays inside them. Emergency: \"any sudden or unforeseen event that requires immediate action.\" Notify SC811 and the operators as soon as practicable; operators make contact within three hours. Calling it an emergency does not remove liability for damage. Bad weather: ice or snow can be an extraordinary circumstance that lets an operator post Code 110 with a later marking date. Complaints: file with the Attorney General's Office within 45 days of the incident. Fine amounts are not in the manual and were not confirmed.", "source": "SC811 Excavator Manual 2026 pp. 9-23, 27-35; S.C. Code 58-36-10 to 58-36-120", "url": "https://sc811.com/wp-content/uploads/2026/05/Excavator-Manual-2026.pdf", "checked": "2026-11-20", "edition": "2026 Excavator Manual", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "fine amounts"}},
{"lib": "field", "chunk": {"id": "dig-ok-tickets-1", "state": "OK", "tier": "core", "title": "Oklahoma 811: ticket types, large projects, emergencies, exemptions", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Oklahoma ticket types (OKIE811 Excavator Guide 2026 pp. 16-19): Normal; Emergency; Demolition (7 business days, after permits); Design Survey (operators have 14 calendar days; \"No excavation may take place on a design or survey notice\"); Pre-Excavation Meeting request for large projects (file 14 or more days ahead); Re-Mark / Extend, both add 14 days; Second Notice when an operator missed its response or the locate is incomplete. Large project: over the ticket size limits or expected to last more than 90 days. \"Watch and protect\": if an operator has posted that response, do not dig within ten feet of its marks without its person there (63 O.S. 142.6). Emergency: an \"unavoidable situation that poses a danger to life, health, or property.\" Digging \"may begin immediately, providing reasonable precautions are taken,\" and operators must be told promptly. A false emergency can make you pay the response costs. Exempt: farm cultivation; a person digging on their own property, unless in an easement or right-of-way or working for hire. A repeat willful violator can be barred by court order from excavating. Fine amounts are not in the guide and were not confirmed.", "source": "OKIE811 Excavator Guide (Feb 2026; law text as of Nov 1, 2025) pp. 6, 10-19, 24-39; 63 O.S. 142.6", "url": "https://okie811.org/wp-content/uploads/2026/07/2026-Excavator-Guide-Digital-.pdf", "checked": "2026-11-20", "edition": "Excavator Guide, February 2026", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "fine amounts"}},
{"lib": "field", "chunk": {"id": "dig-ia-tickets-1", "state": "IA", "tier": "core", "title": "Iowa 811: ticket types, fines, farm exemption", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Iowa ticket types (Iowa One Call manual pp. 15-19): Regular locate; Emergency locate; Dig-In notice (reports damage or contact; it does not create a locate ticket); Joint meet (a preconstruction meeting for complex sites, which can stand in for white-lining); Design information request (maps for designers); Design locate request (available after a five working day wait). Large sites can be planned on one Parent Ticket that the system splits into smaller tickets. Emergency: \"a condition where there is clear and immediate danger to life or health\" or loss of essential service. You may start at once with reasonable care and must notify the center as soon as practical. Falsifying an emergency can be penalized. Civil penalties (Iowa Code 480.6): gas or hazardous liquid pipelines, up to $10,000 per violation per day, capped at $500,000; other lines, up to $1,000 per day, capped at $20,000. Normal farming is not excavation, but ripping deeper than 15 inches is not \"normal farming.\" Homeowners are not exempt. Operators do not locate for depth.", "source": "Iowa One Call Excavator Manual (July 2024) pp. 2, 12-19, 32-46, 54-56; Iowa Code ch. 480", "url": "https://iowaonecall.com/wp-content/uploads/2024/08/iaoc-excavator-manual-2024.pdf", "checked": "2026-11-20", "edition": "Excavator Manual published July 2024", "confidence": "medium", "kind": "summary", "license": "summary"}}]$kb$::jsonb) with ordinality t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = t.e->'chunk'->>'id');
-- dig-ca-overview-1 replaces dig-ca (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ca-overview-1", "state": "CA", "tier": "core", "title": "California 811: the dig law in short (USA North 811, DigAlert)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "California's dig law is Government Code 4216 to 4216.24. Two centers answer 811: USA North 811 (north and central) and DigAlert (south). Mark the dig area in white first: the law says the excavator \"shall delineate the area to be excavated\" before calling. Call at least 2 working days and not more than 14 calendar days before digging. Working days are Monday to Friday, 7 AM to 5 PM, not holidays, and the call day does not count. Do not dig until every operator on the ticket has marked or answered through electronic positive response. A ticket is good for 28 days from issue; renew by the end of day 28. If it expires while work goes on, stop and get a new ticket. Tolerance zone: 24 inches on each side of the field mark. Inside it, find the line with hand tools before using power equipment. Hit a line: call the operator right away; call 911 if gas or hazardous liquid is escaping; tell the 811 center within 48 hours.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-2/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-ca"}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$dig-ca$kb$
   and ($kb$dig-ca-overview-1$kb$ = $kb$dig-ca$kb$ or not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = $kb$dig-ca-overview-1$kb$));
-- dig-az-overview-1 replaces dig-az (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-az-overview-1", "state": "AZ", "tier": "core", "title": "Arizona 811: the dig law in short (Arizona 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Arizona's dig law is A.R.S. 40-360.21 to 40-360.32, enforced by the Arizona Corporation Commission. One center: Arizona 811. Mark the dig area with white lining before you call (40-360.22(C)); a person digging on a single-family home lot is excused. Operators must mark \"as promptly as practicable, but not later than two working days.\" Working days skip Saturday, Sunday, legal holidays and the Friday after Thanksgiving. You may not start \"before the location and marking are complete or the excavator is notified that marking is unnecessary.\" Marks are good for 15 working days from the date of marking. If work goes on, give notice at least 2 working days before they run out. Within 24 inches of a marked line, expose it carefully with hand tools and support it. Hit a line: tell the operator right away; gas or hazardous material, also call 911. Leave the hole open until the operator arrives. Fine: up to $5,000 per violation.", "source": "A.R.S. 40-360.21 to 40-360.28 (azleg.gov; statute copy in Southwest Gas \"Arizona Dig Law\" booklet, rev. Aug 2017)", "url": "https://azleg.gov/ars/40/00360-22.htm", "checked": "2026-11-20", "edition": "Statute as posted on azleg.gov, read Nov 20, 2026", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-az"}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$dig-az$kb$
   and ($kb$dig-az-overview-1$kb$ = $kb$dig-az$kb$ or not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = $kb$dig-az-overview-1$kb$));
-- dig-nv-overview-1 replaces dig-nv (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-nv-overview-1", "state": "NV", "tier": "core", "title": "Nevada 811: the dig law in short (USA North 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Nevada's dig law is NRS 455.080 to 455.180 with rules in NAC 455. One center: USA North 811. Call at least 2 working days (7 AM to 5 PM, not weekends or holidays, call day not counted) and not more than 28 calendar days before digging. Mark the dig area in white first. Wait for every operator: the handbook says excavators \"are required by law to wait until all operators\" have given a positive response, even if the start time on the ticket has passed. A ticket is good for 28 calendar days from the date and time of the notification. It can be extended twice, 28 days each; after that the regulation requires a new notification (NAC 455.165). That is 84 days at most on one ticket. Hand tools only within 24 inches on either side of the outside of the line. Hit a line: notify the operator right away; in an emergency also 911.", "source": "USA North 811 Nevada Excavation Handbook (rev. Jan 2025) pp. 3-8, 21; NRS 455.110; NAC 455.165", "url": "https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf", "checked": "2026-11-20", "edition": "Handbook revised January 2025; NAC 455 revised Aug 2026", "confidence": "high", "kind": "summary", "license": "summary", "supersedes": "dig-nv"}$kb$::jsonb
