-- dig-tx-overview-1 replaces dig-tx (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-tx-overview-1", "state": "TX", "tier": "core", "title": "Texas 811: the dig laws in short (Texas811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Texas has two layers: Utilities Code chapter 251 (the one-call law for all lines) and Railroad Commission rule 16 TAC chapter 18 for pipelines (gas, hazardous liquid, CO2). Call 811 or use the Texas811 portal. Notice: at least 48 hours before digging, not counting weekends and legal holidays, and not more than 14 days ahead. Ticket life: 14 working days for pipeline locates unless you and the operator agree otherwise in writing. Not done: refresh the ticket for the area still to dig. Texas811 sends updates with a 2 business day notice. Tolerance zone for pipelines: half the pipe diameter plus at least 18 inches on each side. Wait for a positive response (marks, \"all clear\" or \"no conflict\"). None: give a second notice; if there is still none after 4 hours you may begin. Hit a pipeline: notify the operator through 811 within 1 hour, call 911 for a release, and file a damage report with the Railroad Commission within 30 days.", "source": "16 TAC ch. 18 (Railroad Commission; sections as amended eff. Feb 12, 2018); Tex. Util. Code ch. 251", "url": "https://www.rrc.texas.gov/media/ap2ck4pb/chapter18-all-effective-feb12-2018.pdf", "checked": "2026-11-20", "edition": "16 TAC ch. 18 as in effect Feb 12, 2018 (latest amendment shown)", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-tx"}$kb$::jsonb
