-- dig-fl-overview-1 replaces dig-fl (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-fl-overview-1", "state": "FL", "tier": "core", "title": "Florida 811: the dig law in short (Sunshine 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Florida's dig law is chapter 556, the Underground Facility Damage Prevention and Safety Act. One center: Sunshine 811. Notice: \"not less than 2 full business days before beginning any excavation\" (10 full business days for underwater work). A ticket is valid for 30 calendar days. Not finished: give another notice for the part still to dig. Tolerance zone: 24 inches from the outer edge of either side of the marked line. Inside it, \"use increased caution\": hand dig, pothole, soft dig or vacuum. You must check the positive responses before you dig. Pre-mark in white when the site can't otherwise be identified. Hit a line: \"immediately notify the member operator\"; if gas or a hazardous substance escapes, call 911. Citations are $500 plus court costs, $2,500 for hazardous material pipelines.", "source": "Fla. Stat. ch. 556 (2025): 556.102, 556.105, 556.107, 556.108, 556.109, 556.114, 556.116", "url": "https://flsenate.gov/Laws/Statutes/2025/Chapter556/All", "checked": "2026-11-20", "edition": "2025 Florida Statutes", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-fl"}$kb$::jsonb
