-- dig-wa-overview-1 replaces dig-wa (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-wa-overview-1", "state": "WA", "tier": "core", "title": "Washington 811: the dig law in short (Washington 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Washington's dig law is RCW 19.122, enforced by the Utilities and Transportation Commission (UTC). Mark the boundary of the dig \"with white lining or, when necessary, white pin flags,\" then call 811. Notice: \"not less than two full business days and not more than 10 full business days\" before the work-to-begin date. Since January 1, 2026 you \"may not commence excavation until the excavator has received positive response\" from every operator with lines in the area. Marks expire 45 calendar days after you gave notice; to dig after that, give a new notice. Marks are accurate to within 24 inches of the outside of the line on both sides. Find the exact location before digging there: hand digging when practical, vacuum or air tools. Hit a line: tell the operator and 811, call 911 if it is an emergency, don't bury it, and report the damage to the UTC within 45 days.", "source": "RCW 19.122.020, .030, .031, .040, .050, .053, .055, .070 (through Laws 2025 c 292)", "url": "https://lawfilesext.leg.wa.gov/law/RCWPDF/RCW%20%2019%20%20TITLE/RCW%20%2019%20.122%20%20CHAPTER/RCW%20%2019%20.122%20%20COMBINEDCHAPTER.pdf", "checked": "2026-11-20", "edition": "RCW as amended through Laws of 2025 chapter 292", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-wa"}$kb$::jsonb
