-- dig-or-overview-1 replaces dig-or (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-or-overview-1", "state": "OR", "tier": "core", "title": "Oregon 811: the dig rules in short (Oregon 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Oregon's dig rules are ORS 757.542 to 757.562 and OAR chapter 952, written by the Oregon Utility Notification Center (Oregon 811). Pre-mark the dig area in white, then call at least 2 full business days and not more than 10 business days before digging. Do not start until you have \"received a response from each operator of underground facilities in the area.\" Ticket life: the Center's 2026 Addendum says the rule was changed \"from 45 days to 30 days,\" effective January 8, 2026. Older copies of the rule and the Center's own FAQ page still say 45 calendar days, so the current number is not confirmed. Until you check with Oregon 811, plan on 30 days. Past ticket life, call in a new locate request. Tolerance zone: 24 inches around the outside of the line on all sides. Use hand tools or other non-invasive methods there. Hit a line: tell the operator right away; gas or hazardous liquid release, call 911. Don't bury it without the operator's OK.", "source": "OAR 952-001-0010, -0050, -0070, -0090 (Oregon Utility Notification Center); 2026 Addendum to the Oregon Standards Manual (Mar 12, 2026)", "url": "https://digsafelyoregon.com/wp-content/uploads/2026/03/2026-Addendum-to-the-Oregon-Standards-Manual_Final.pdf", "checked": "2026-11-20", "edition": "2026 Addendum, last updated March 12, 2026", "effective": "2026-01-08", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life 30 vs 45 days: the official rule text with the 2026 change was not opened", "supersedes": "dig-or"}$kb$::jsonb
