-- dig-co-overview-1 replaces dig-co (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-co-overview-1", "state": "CO", "tier": "core", "title": "Colorado 811: the dig law in short (Colorado 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Colorado's dig law is C.R.S. 9-1.5-101 to 9-1.5-108, with the Underground Damage Prevention Safety Commission hearing violations. One center: Colorado 811. Notice: \"at least two (2) full business days prior to any excavation,\" not counting the call day. Marks are good for 30 days from the ticket's due date, or until you can't see them, whichever is first. To go on, notify Colorado 811 at least 2 business days before the 30 days end; once it has run out you need a new ticket. Tolerance zone: the width of the line plus 18 inches on each side. Use non-destructive digging there (hand or vacuum). Check that every member on the ticket has posted a positive response before you dig. If one has not by the locate-by date, send an Excavator Re-Notification first. Hit a line: stop, notify 811 and the operator right away; gas release, clear the area and call 911.", "source": "Colorado 811 Excavator Handbook (last update Nov 2022) pp. 5-23, 27-45; C.R.S. 9-1.5-103", "url": "https://a-us.storyblok.com/f/1021538/x/160e66dfe5/excavator-handbook.pdf", "checked": "2026-11-20", "edition": "Handbook last updated November 2022", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-co"}$kb$::jsonb
