-- dig-ut-overview-1 replaces dig-ut (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ut-overview-1", "state": "UT", "tier": "core", "title": "Utah 811: the dig law in short (Blue Stakes of Utah 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Utah's dig law is Utah Code Title 54, Chapter 8a. One center: Blue Stakes of Utah 811. Notice: not \"less than 48 hours before excavation begins\" and not \"more than 14 days before.\" The 48 hours count business days only; business hours are 8 AM to 4 PM, Monday to Friday, not holidays. A notice is \"valid for 21 days from the day on which the notice is given.\" To keep going, renew at least 48 hours and no more than 7 calendar days before it expires. Blue Stakes gives an update a different ticket number. Tolerance zone: 24 inches on either side of the outside edge of the mark (or half the marked diameter plus 24 inches from the center). No power equipment inside the zone until you have found the exact location with hand tools. Operator did not mark or answer in 48 hours: file a no response notice; the operator then has 4 business hours. Hit a line: tell the operator right away; gas, electric or danger to life, call 911. No backfill until the operator says so.", "source": "Utah Code 54-8a-2, -4, -5, -5.5, -7, -8, -12 (as amended by 2024 ch. 369)", "url": "https://le.utah.gov/xcode/Title54/Chapter8A/C54-8a_1800010118000101.pdf", "checked": "2026-11-20", "edition": "Utah Code as amended by the 2024 General Session (ch. 369)", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-ut"}$kb$::jsonb
