-- dig-ga-overview-1 replaces dig-ga (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ga-overview-1", "state": "GA", "tier": "core", "title": "Georgia 811: the dig law in short (Georgia 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Georgia's dig law is the Georgia Underground Facility Protection Act, O.C.G.A. 25-9, enforced by the Public Service Commission. One center: Georgia 811. Notice: the notice period starts at 7 AM on the first business day after Georgia 811 gets your request and runs at least 2 business days, so a Monday request is good to dig Thursday at 7 AM. A request after 4:30 PM counts as the next business day. You may start early only if every owner has already answered clear or marked. Check the Positive Response Information System (PRIS) before digging. A locate request is good for 30 calendar days. Georgia 811 allows a normal ticket to be updated two times (90 days); each update is a new ticket number. Tolerance zone: the width of the line plus 18 inches on either side. Hit a line: stop, notify Georgia 811 and the owner; gas or hazardous liquid, call 911. Fines up to $10,000 per violation.", "source": "O.C.G.A. 25-9-3, 25-9-4, 25-9-6, 25-9-7, 25-9-8, 25-9-12, 25-9-14 (as printed by Georgia 811, eff. Sept 1, 2022)", "url": "https://georgia811.com/wp-content/uploads/2025/03/Georgia-Dig-Law_090122.pdf", "checked": "2026-11-20", "effective": "2022-09-01", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-ga"}$kb$::jsonb
