-- dig-nc-overview-1 replaces dig-nc (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-nc-overview-1", "state": "NC", "tier": "core", "title": "North Carolina 811: the dig law in short (NC811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "North Carolina's dig law is the Underground Utility Safety and Damage Prevention Act, G.S. Chapter 87, Article 8A (amended in 2025). One center: NC811. Notice: at least 3 full working days before the start date (10 to 20 for work near underwater lines). Working days are every day but Saturday, Sunday and State holidays. A notice expires 28 calendar days after the work start date. To keep digging, give a new notice the same way; NC811 calls it an update and it gets a new ticket number. Check positive response before you dig. Tolerance zone: 24 inches on each side of the outside edge of the mark, or half the diameter plus 24 inches from the centerline when the size is known. No mechanized equipment in the zone until you can see the line. Hit a line: notify NC811 and the operator right away; gas, electricity or danger, call 911 first. No backfill until cleared.", "source": "N.C.G.S. 87-117, 87-120 to 87-127, 87-129 (Article 8A, as amended by S.L. 2025-21)", "url": "https://www.ncleg.net/EnactedLegislation/Statutes/HTML/ByArticle/Chapter_87/Article_8A.html", "checked": "2026-11-20", "edition": "Statute as amended by Session Law 2025-21", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-nc"}$kb$::jsonb
