-- dig-ny-overview-1 replaces dig-ny (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ny-overview-1", "state": "NY", "tier": "core", "title": "New York 811: the dig rules in short (UDig NY, New York 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "New York's dig rules are 16 NYCRR Part 753 (\"Code Rule 753\") under General Business Law Article 36, enforced by the Public Service Commission. Two centers: UDig NY upstate and New York 811 for New York City and Long Island. Notice: \"at least two but not more than ten working days, not including the date of the call.\" There is no ticket expiry date. If you put the start off by more than ten working days, give a new notice. Do not start until you have heard from \"each and every operator\" that its lines are marked or that it has none. Use the Automated Positive Response system where there is one. Tolerance zone: half the known diameter plus two feet on each side of the center line (two feet each side if the size is not known). Verify the line's exact location before power equipment goes in the zone; gas and liquid petroleum lines must be found with hand-dug test holes. Hit a line: tell the operator right away; gas, liquid or electric emergency, clear the area and call 911.", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; booklet updated May 9, 2025", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-ny"}$kb$::jsonb
