-- dig-il-overview-1 replaces dig-il (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-il-overview-1", "state": "IL", "tier": "core", "title": "Illinois 811: the dig law in short (JULIE; Chicago is separate)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Illinois's dig law is the Underground Utility Facilities Damage Prevention Act, 220 ILCS 50, rewritten effective January 1, 2025 and enforced by the Illinois Commerce Commission. JULIE is the one-call center everywhere outside the City of Chicago; Chicago runs its own system (811 Chicago). Notice: \"not less than 2 days but no more than 10 days in advance.\" A \"day\" skips Saturdays, Sundays, JULIE holidays and the day of the notice. A normal notice is good for 25 days from the first request. An extension can be asked for from day 20 and adds 25 days. Pre-mark the dig area in white (black when there is snow on the ground). Since January 1, 2026: confirm every notified operator has posted a positive response before you dig. Tolerance zone: one and one-half feet (18 inches) on either side of the outside edge of the marked line. Hit a line: notify the owner and JULIE right away; gas or hazardous material escaping, call 911.", "source": "220 ILCS 50/2, 4, 5.1, 5.2, 5.3, 6, 7, 10, 11 (as amended by P.A. 103-614, eff. Jan 1, 2025)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "effective": "2025-01-01", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-il"}$kb$::jsonb
