-- dig-oh-overview-1 replaces dig-oh (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-oh-overview-1", "state": "OH", "tier": "core", "title": "Ohio 811: the dig law in short (OHIO811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Ohio's dig law is O.R.C. 3781.25 to 3781.38 (amended June 9, 2026); complaints go to the Underground Technical Committee at the PUCO. One center: OHIO811. Oil and gas producers answer through a separate group reached by the same call. Notice: \"at least two working days, not including the day of the notification,\" and \"not more than sixteen calendar days before commencing excavation.\" The law and the June 2026 manual give no ticket expiry date. Keep the ticket for the whole job and ask for a remark when marks fade. Premark the dig in white paint unless an exception applies. Check Positive Response before you go to the job; code 999 means an owner has not answered by the legal start. Tolerance zone: the width of the line plus 18 inches on each side. Dig there carefully, with a second person watching the bucket. Hit a line: get everyone safe, stop, notify the utility and OHIO811; anything flammable, toxic or corrosive escaping, call 911.", "source": "OHIO811 Excavator Manual (rev. June 2026) pp. 5-7, 10-17, 20-24, 40; O.R.C. 3781.25 to 3781.32", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "checked": "2026-11-20", "edition": "Manual revised June 2026", "confidence": "high", "kind": "summary", "license": "summary", "supersedes": "dig-oh"}$kb$::jsonb
