-- dig-mi-overview-1 replaces dig-mi (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-mi-overview-1", "state": "MI", "tier": "core", "title": "Michigan 811: the dig law in short (MISS DIG 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Michigan's dig law is the MISS DIG Underground Facility Damage Prevention and Safety Act, 2013 PA 174 (MCL 460.721 to 460.733), enforced by the Michigan Public Service Commission. One center: MISS DIG 811. Notice: \"at least 72 hours, but not more than 14 calendar days, before the start.\" Hours on non-business days do not count. A ticket is \"valid for 21 days from the start date,\" or 180 days when the notice says the work will take longer. Past that, or if digging did not start in time, get a new ticket. Caution zone: 48 inches on either side of the marks. Before digging there, expose every marked line by soft excavation (hand or vacuum). Check positive response. No response on a ticket is a reason to stop near there and give additional notice. Hit a line: notify the owner right away; gas or liquid escaping or danger to life, call 911.", "source": "MCL 460.723, 460.725, 460.726a, 460.727, 460.731, 460.732 (2013 PA 174; compilation through PA 91 of 2026)", "url": "https://www.legislature.mi.gov/documents/mcl/archive/2026/September/mcl-Act-174-of-2013.pdf", "checked": "2026-11-20", "edition": "MCL compilation complete through PA 91 of 2026", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-mi"}$kb$::jsonb
