-- dig-pa-overview-1 replaces dig-pa (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-pa-overview-1", "state": "PA", "tier": "core", "title": "Pennsylvania 811: the dig law in short (Pennsylvania One Call, PA 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Pennsylvania's dig law is the Underground Utility Line Protection Law (Act 287 of 1974, as amended by Act 50 of 2017 and Act 127 of 2024), 73 P.S. 176 and after. The Public Utility Commission enforces it through its Damage Prevention Committee. One center: Pennsylvania One Call (PA 811). Notice: \"not less than three nor more than ten business days in advance of beginning excavation.\" Complex projects: at least ten business days. The law gives no number of days a ticket lasts. It says to call again if you leave the site for more than two business days (unless you made other arrangements with the owners). Ticket life is not confirmed; go by PA One Call. Tolerance zone: within eighteen inches of the outside wall or edge of the line. Use prudent techniques there, such as hand-dug test holes or vacuum. Check the owners' responses (KARL) before digging. If an owner fails to respond you may proceed on the lawful start date, with due care. Hit a line: tell the owner right away; gas or liquid escaping, call 911.", "source": "73 P.S. 176, 180, 182.10 (Underground Utility Line Protection Law; FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-180/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life in days", "supersedes": "dig-pa"}$kb$::jsonb
