-- dig-de-overview-1 replaces dig-de (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-de-overview-1", "state": "DE", "tier": "core", "title": "Delaware 811: the dig law in short (Miss Utility of Delmarva)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Delaware's dig law is the Underground Utility Damage Prevention and Safety Act, 26 Del. C. chapter 8, enforced by the Public Service Commission. Call 811 (Miss Utility of Delmarva). Notice: \"not less than 3 business days, but no more than 12 business days\" before work begins. A ticket \"is valid for 12 business days after the day on which the ticket is transmitted.\" \"On the thirteenth day, the ticket will expire, and an update, remark, or new excavation ticket shall be required.\" \"No excavation may begin until a positive response code of clear or no conflict or marked is received.\" Tolerance zone: 24 inches from the outside wall or edge of the line. No mechanized equipment in it except to remove pavement; vacuum excavation is allowed; hand dig. White line marking is highly recommended when the exact location can't be given. Hit a line: report it to the owner immediately; dangerous gas or liquid escaping, call 911.", "source": "26 Del. C. 802, 803, 805, 806, 808, 810 (Underground Utility Damage Prevention and Safety Act; through 85 Del. Laws c. 345)", "url": "https://delcode.delaware.gov/title26/c008/sc01/index.html", "checked": "2026-11-20", "edition": "Delaware Code online, through 85 Del. Laws c. 345", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-de"}$kb$::jsonb
