-- dig-dc-overview-1 replaces dig-dc (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-dc-overview-1", "state": "DC", "tier": "core", "title": "District of Columbia 811: the dig law in short (District One Call, 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "The District of Columbia's dig law is D.C. Code Title 34, Chapter 27. Call 811 (District One Call). Notice: at least 96 hours and not more than 10 days before work begins, not counting Saturdays, Sundays and legal holidays. A notice is good for 15 days, not counting weekends and legal holidays. Three days before that ends, or when marks can't be read, ask the one-call center for a re-mark; re-marking is done within 48 hours. No digging until the one-call center confirms the operators have answered (they have 72 hours). Marks are within 2 feet of the outermost part of the line. Within 18 inches of it, expose the line by hand digging. Hit a line: notify the operator immediately; gas or liquid release, also 911. No backfill over a damaged line without the operator's permission. Fines: $2,500 first violation, $5,000 second, $10,000 third or later.", "source": "D.C. Code 34-2704 to 34-2709 (through D.C. Law 23-186, Mar. 16, 2021)", "url": "https://code.dccouncil.gov/us/dc/council/code/titles/34/chapters/27/index.full.html", "checked": "2026-11-20", "edition": "D.C. Code online, through D.C. Law 23-186 (2021)", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-dc"}$kb$::jsonb
