-- dig-va-overview-1 replaces dig-va (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-va-overview-1", "state": "VA", "tier": "core", "title": "Virginia 811: the dig law in short (Virginia 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Virginia's dig law is the Underground Utility Damage Prevention Act, Va. Code 56-265.14 to 56-265.32, enforced by the State Corporation Commission. One center: Virginia 811. Wait: operators have 48 hours beginning at 7:00 a.m. the next working day after your locate request, so a Monday request is good Thursday at 7 AM. You may start sooner only when every operator has marked or posted a positive response that allows digging. A notice is \"valid for 15 working days\" from 7:00 a.m. the next working day after the request (or the scheduled date, if later). Three working days before it runs out, or when marks can't be read, request an update; Virginia 811 gives an update or re-mark a new request number. A re-mark is good for another 15 working days. Mark the site boundary in white paint, if practical, when you can't give an exact location. One request covers no more than one-third of a mile and only what can be dug in 15 working days. The hand-dig distance (2 feet in section 56-265.24) and fine amounts were not confirmed in this pass.", "source": "Va. Code 56-265.17 (2023 amendments); Virginia 811 \"Ticket Types\" sheet (May 15, 2026)", "url": "https://law.lis.virginia.gov/vacode/56-265.17/", "checked": "2026-11-20", "edition": "Section as amended in 2023 (chs. 299 and 300)", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "hand-dig distance and fine amounts", "supersedes": "dig-va"}$kb$::jsonb
