-- dig-wv-overview-1 replaces dig-wv (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-wv-overview-1", "state": "WV", "tier": "core", "title": "West Virginia 811: the dig law in short (West Virginia 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "West Virginia's dig law is W. Va. Code Chapter 24C. One center: West Virginia 811. Notice: \"Not less than forty-eight hours, excluding Saturdays, Sundays and federal or state legal holidays,\" and not more than ten work days before work begins. Changing the start date or time: tell the one-call system at least 24 hours ahead, not counting weekends and holidays. The section sets no ticket life in days and no tolerance zone in inches; those are not confirmed here, so go by the ticket and West Virginia 811. Each equipment operator must be told to avoid damage, \"including hand digging, when necessary,\" to keep a clearance \"as may be reasonably necessary\" from lines given the reach of the cutting edge, to protect marks and stakes, and to support lines during work and backfill. Line hit: report it immediately and give the operator reasonable time to repair. An emergency: alert the public and call 911. Damage that is not an emergency: notify the one-call system within 24 hours. Failing to notify or to report is a misdemeanor with a fine of \"not more than $5,000,\" and you owe the repair cost.", "source": "W. Va. Code 24C-1-5 (code.wvlegislature.gov)", "url": "https://code.wvlegislature.gov/24C-1-5/", "checked": "2026-11-20", "edition": "W. Va. Code as posted Nov 20, 2026 (last act shown: 2006 SB 439)", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life and tolerance zone", "supersedes": "dig-wv"}$kb$::jsonb
