update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-md-overview-1", "state": "MD", "tier": "core", "title": "Maryland 811: the dig law in short (Miss Utility)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Maryland's dig law is Public Utilities Article Title 12, Subtitle 1, enforced by the Maryland Underground Facilities Damage Prevention Authority. Call 811 (Miss Utility). Pick a start date \"not sooner than 3 business days after the ticket is initiated\" and not later than 12 business days after. Business days are Monday to Friday, 7 AM to 5 PM, not holidays; a ticket taken after hours counts from the next business morning. \"A ticket is valid for 12 business days after the selected start work date.\" If the work won't be done in that time, \"repeat the notification\" the same way as the first. Ticket Check (positive response) is mandatory for owner-members. Check it before digging: 866-821-4226 or online. Code 11 (critical facilities) is not a go-ahead. Emergency tickets: owners respond within two hours. The 18-inch hand-dig rule and fine amounts come from the statute, were not re-read today and are not confirmed here.", "source": "Md. Code, Public Utilities 12-124, 12-125 (FindLaw); Miss Utility Maryland page (missutility.net/maryland)", "url": "https://www.missutility.net/maryland/", "checked": "2026-11-20", "edition": "Miss Utility page as posted Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "18-inch rule and fine amounts not re-read", "supersedes": "dig-md"}$kb$::jsonb
