update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-nj-overview-1", "state": "NJ", "tier": "core", "title": "New Jersey 811: the dig rules in short (New Jersey One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "New Jersey's dig law is the Underground Facility Protection Act (N.J.S.A. 48:2-73 and after) with rules in N.J.A.C. 14:2, enforced by the Board of Public Utilities. Call 811 (New Jersey One Call). Notice: \"no less than three business days before the beginning of the excavation.\" Start within 10 business days of the notice. The notice \"shall remain valid for 45 business days from the notification.\" Digging after that needs a new notification with the normal wait. Operators must post an electronic positive response within three business days and mark out or tell you they have no lines there. You may mark the edge of the site in white; it is optional. Marks are paint, at intervals of 25 feet or less. Hit a gas, petroleum or hazardous liquid line: \"immediately call 911,\" then the operator, or the One-Call center at 811 if you can't reach the operator. Fines: $1,000 to $2,500 per day, up to $25,000 for a related series. The hand-dig distance (2 feet in the statute) was not confirmed in the text read.", "source": "N.J.A.C. 14:2-3.1, 3.2, 3.5, 3.6, 4.2, 4.4, 5.2, 6.2 (BPU One-Call rules, 2021 readoption text)", "url": "https://nj.gov/bpu/pdf/rules/Chapter%202%20One%20Call%20Rules%2010.28.21%20Clean%20Version.pdf", "checked": "2026-11-20", "edition": "BPU rule text dated Oct 28, 2021 (readoption proposal)", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "hand-dig distance; this is the 2021 proposal text, not the current code", "supersedes": "dig-nj"}$kb$::jsonb
