update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ma-overview-1", "state": "MA", "tier": "core", "title": "Massachusetts 811: the dig rules in short (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Massachusetts uses Dig Safe as its one-call center (call 811); the Department of Public Utilities enforces the state's Dig Safe law. Pre-mark the dig area in white (paint, flags, stakes or whiskers), then call at least 72 hours ahead, not counting weekends and holidays, and not more than 30 days ahead. Ticket life: tickets expire 30 days from the day of issue. In every Dig Safe state a ticket expires if digging does not start within 30 days. Renew with at least 72 hours' notice (weekends and holidays not counted) so there is no gap; if the scope of work changes, get a new ticket instead. Whether a renewal prints a new number is not confirmed. Tolerance zone: the width of the line plus 18 inches on each side. Hand dig or use vacuum equipment there; no machines until the line is verified. Power equipment may remove pavement only to the depth of the pavement. Dig Safe only notifies its members. Call non-member owners (often town water and sewer) yourself.", "source": "Dig Safe Excavator Manual (version Aug 2025; laws table updated 6/5/25) pp. 4-5, 9, 11, 14-19, 25-27, 31", "url": "https://digsafe.com/data/file_uploads/Dig%20Safe%20Excavator%20Manual%20November%202025.pdf", "checked": "2026-11-20", "edition": "Manual version August 2025", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "new ticket number on renewal", "supersedes": "dig-ma"}$kb$::jsonb
