update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ct-overview-1", "state": "CT", "tier": "core", "title": "Connecticut 811: the dig rules in short (Call Before You Dig)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Connecticut's dig law is Conn. Gen. Stat. 16-345 to 16-359 with regulations R.C.S.A. 16-345-1 to 16-345-9. The Public Utilities Regulatory Authority (PURA) oversees and enforces it. Call 811 (Call Before You Dig, CBYD). Notice: \"at least two full days, excluding Saturdays, Sundays and holidays, but not more than thirty (30) days\" before digging. The app's table gives a 30-day ticket life from the regulation; that and the hand-dig distance were not on the page read today and are not confirmed here. Forgetting to call is not an emergency. An emergency excavation is one \"necessary to correct an emergency involving danger to life, health, or property.\" Hit or touch a line: \"Immediately and directly report the contact or damage to the affected public utility.\" For a gas escape or other danger, also alert emergency personnel (911) and keep people away. Violations can bring a civil penalty from PURA; the amount was not on the page.", "source": "R.C.S.A. 16-345-1 to 16-345-9 as described on the PURA \"CBYD Current Provisions\" page", "url": "https://portal.ct.gov/PURA/Gas-Pipeline-Safety/Call-Before-You-Dig/CBYD-Current-Provisions", "checked": "2026-11-20", "edition": "PURA page as posted Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life, tolerance zone and penalty amounts", "supersedes": "dig-ct"}$kb$::jsonb
