update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ks-overview-1", "state": "KS", "tier": "core", "title": "Kansas 811: the dig law in short (Kansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Kansas's dig law is the Kansas Underground Utility Damage Prevention Act, K.S.A. 66-1801 to 66-1816, enforced by the Kansas Corporation Commission. One center: Kansas 811. Notice: \"at least two full working days but not more than 20 calendar days before the scheduled excavation start date.\" The notice, or any update, is \"valid for 20 calendar days after the excavation start date\" (changed from 15 days on January 1, 2024). Ticket only what you can reasonably finish in that time. To go on, update the notice. Do not make repeated remark requests unless the cause was out of your control; the Commission has warned of fines for needless updates. Whiteline the dig area when the operator asks for it. Pre-engineered and permitted projects still need the notice before digging starts. The tolerance zone (24 inches in K.S.A. 66-1802) and fine amounts were not re-read today and are not confirmed here.", "source": "K.S.A. 66-1804 (ksrevisor.gov, as amended eff. Jan 1, 2024)", "url": "https://ksrevisor.gov/statutes/chapters/ch66/066_018_0004.html", "checked": "2026-11-20", "effective": "2024-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "tolerance zone and fine amounts", "supersedes": "dig-ks"}$kb$::jsonb
