-- dig-tn-overview-1 replaces dig-tn (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-tn-overview-1", "state": "TN", "tier": "core", "title": "Tennessee 811: the dig law in short (Tennessee 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Tennessee's dig law is the Underground Utility Damage Prevention Act, T.C.A. 65-31-101 and after, with an Enforcement Board at the Tennessee Public Utility Commission. One center: Tennessee 811. Notice: \"at least three (3) working days prior to the actual date of excavation\" and not more than ten full working days ahead. A ticket is good for \"fifteen (15) calendar days from the actual date specified to start.\" To keep digging, give a new notice at least three working days before the fifteenth day runs out; Tennessee 811 says you are then \"given a new ticket number.\" When the digging is done, stop updating. Mark the dig area \"with white paint, or by electronic white lining\" unless an exception applies (for example the ticket gives a precise location). A property owner using non-mechanized tools on their own property is exempt. Within 100 feet of the edge of a street or highway, if an operator fails to locate in time the excavator is authorized to proceed. The tolerance zone (24 inches in 65-31-108) and penalty amounts were not re-read today and are not confirmed here.", "source": "T.C.A. 65-31-106 (FindLaw copy, current as of Jan 2, 2024); Tennessee 811 law page and FAQ", "url": "https://codes.findlaw.com/tn/title-65-public-utilities-and-carriers/tn-code-sect-65-31-106/", "checked": "2026-11-20", "edition": "FindLaw copy current as of January 2, 2024", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "tolerance zone and penalty amounts", "supersedes": "dig-tn"}$kb$::jsonb
