-- dig-al-overview-1 replaces dig-al (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-al-overview-1", "state": "AL", "tier": "core", "title": "Alabama 811: the dig law in short (Alabama 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Alabama's dig law is Ala. Code Title 37, Chapter 15, with the Underground Damage Prevention Authority enforcing it. One center: Alabama 811. A 2026 rewrite (SB205) takes effect January 1, 2027; the notice and ticket-life numbers below are the same before and after. Notice: \"at least two but not more than 10 working days prior to the start of the proposed excavation\" (demolition or blasting: 2 working days to 30 calendar days). An excavation notice is \"valid for a period of 20 working days from the proposed starting date\" (demolition 30). Renew at least two working days before it expires. Premark the route or edges of the dig in white unless that would get in the way of traffic. Operators post a positive response; you may start early once all of them have. From January 1, 2027 the tolerance zone is the width of the line plus 18 inches on either side: find marked lines by noninvasive methods and keep 18 inches between any line and the cutting edge. Hit a line: notify the operator immediately.", "source": "Ala. Code 37-15-2, -4, -4.1, -4.2, -6, -8, -9, -10 as amended by 2026 SB205 (enrolled), effective Jan 1, 2027", "url": "https://alison.legislature.state.al.us/files/pdf/SearchableInstruments/2026RS/SB205-enr.pdf", "checked": "2026-11-20", "effective": "2027-01-01", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-al"}$kb$::jsonb
