-- dig-ne-overview-1 replaces dig-ne (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ne-overview-1", "state": "NE", "tier": "core", "title": "Nebraska 811: the dig law in short (Nebraska 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Nebraska's dig law is the One-Call Notification System Act, Neb. Rev. Stat. 76-2301 to 76-2334. Since September 1, 2024 the State Fire Marshal investigates complaints and the Underground Excavation Safety Committee sets penalties. One center: Nebraska 811. Notice: the app's table has 2 full business days and not more than 10 business days; operators must respond \"no later than two business days after receipt of a dig ticket.\" Do not call in an area where digging can't reasonably start \"within seventeen calendar days after the ticket start date.\" Marks must be \"within 18 inches on either side of the marking, plus one half of the width of the underground facility.\" Hand dig inside that strip. Hit a line: \"the excavator shall immediately notify the center.\" Do not hide the damage or repair the line without the operator's OK. Penalties: up to $10,000 per day per event for pipeline and fiber optic violations (cap $500,000); up to $5,000 per day per event for other utilities (cap $50,000). Farm tilling and gardening for seeding are not excavation. How long a ticket lasts once digging has started was not confirmed.", "source": "Neb. Rev. Stat. 76-2321, 76-2323, 76-2326 and State Fire Marshal summary (One-Call Notification System Act)", "url": "https://sfm.nebraska.gov/sites/default/files/doc/1.%20Nebraska%20One%20Call%20Act.pdf", "checked": "2026-11-20", "edition": "State Fire Marshal copy of the Act, with changes effective Sept 1, 2024", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life after work starts; notice window not re-read", "supersedes": "dig-ne"}$kb$::jsonb
