-- dig-mo-overview-1 replaces dig-mo (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-mo-overview-1", "state": "MO", "tier": "core", "title": "Missouri 811: the dig law in short (Missouri 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Missouri's dig law is the Underground Facility Safety and Damage Prevention Act, RSMo 319.010 to 319.050 (amended August 28, 2025). One center: Missouri 811. Notice: \"at least two working days, but not more than ten working days, before the expected date\" of starting. You may work in the area on the notice, while the marks can be seen, until the \"notice of intent to excavate expiration date\" printed on the ticket; the number of days is not in this section and is not confirmed here. If you can't start within ten working days, make a relocate request before digging. Marks unusable: ask the center for a remark. White lining (paint, stakes, whiskers) may be used when the site can't be clearly described. Find a line unmarked or marked wrong: notify the center; the owner must contact you or mark it correctly within two hours. Hand or soft digging \"shall be used as a best practice when possible\"; no hand-dig distance is given in this section. Hit a line: notify the center. Gas or hazardous liquid pipeline release: \"immediately contact 911.\" Do not hide or repair damage without the owner's OK.", "source": "RSMo 319.026 (revisor.mo.gov, effective Aug 28, 2025)", "url": "https://revisor.mo.gov/main/OneSection.aspx?section=319.026", "checked": "2026-11-20", "effective": "2025-08-28", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life in days; tolerance zone", "supersedes": "dig-mo"}$kb$::jsonb
