-- dig-ky-overview-1 replaces dig-ky (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ky-overview-1", "state": "KY", "tier": "core", "title": "Kentucky 811: the dig law in short (Kentucky 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Kentucky's dig law is the Underground Facility Damage Prevention Act, KRS 367.4901 to 367.4917. One center: Kentucky 811. Notice: \"not less than two (2) full working days nor more than ten (10) full working days prior to commencing work.\" \"Locate requests are valid for twenty-one (21) calendar days from the day of the initial request.\" Ask for remarking two working days before each 21-day period ends, or sooner if the marks are gone or the plan changes. One request may not cover more than 5,000 feet unless you and the operator agree. Mark the edges of the dig yourself when an operator asks or the area can't be described. Operator did not respond in time: \"the excavator shall submit a second notice.\" If there is still nothing one working day later, an excavator who followed the law is not liable for damage to lines that would have been located (not true for certain gas and hazardous liquid pipelines). Inside the tolerance zone, \"hand-dig or use nonintrusive means.\" Machines are allowed for pavement, rock, and material more than 12 inches in any direction from the located line, with a watcher. Hit a line: stop and notify the operators; flammable, toxic or corrosive escape, call 911.", "source": "KRS 367.4911 (Justia copy, effective Jan 1, 2022)", "url": "https://law.justia.com/codes/kentucky/chapter-367/section-367-4911/", "checked": "2026-11-20", "effective": "2022-01-01", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-ky"}$kb$::jsonb
