-- dig-id-overview-1 replaces dig-id (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-id-overview-1", "state": "ID", "tier": "core", "title": "Idaho 811: the dig law in short (Digline and north Idaho 811 centers)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Idaho's dig law is Idaho Code Title 55, Chapter 22, with the Damage Prevention Board hearing violations. Three centers answer 811: Dig Safe North Idaho 811 (Boundary, Bonner, Kootenai counties), North Idaho 811 (Benewah, Shoshone) and Digline (all other counties). Notice: \"not less than two (2) business days nor more than ten (10) business days before the scheduled date.\" Marks you keep up are good for \"no longer than four (4) consecutive weeks following the date of notification.\" If work has not started within three weeks, give notice again. An Update request extends an active ticket. Pre-mark the path of the dig in white paint. Do not dig \"until all known facilities have been marked.\" Marks missing: send a Second request. Tolerance zone: 24 inches from the outside edges of the line; find the line by hand digging there. Hit a line: notify the owner and the one-number service; danger, call 911 and clear the area. Report the damage to the Board.", "source": "Idaho Guide to Safe Digging 2026-27 (Damage Prevention Board, DOPL) pp. 4, 7, 9-12, 15-20, 29-36; Idaho Code 55-2201 to 55-2212", "url": "https://dopl.idaho.gov/wp-content/uploads/2026/04/DAM-ID-Guide-to-Safe-Digging-26_27.pdf", "checked": "2026-11-20", "edition": "2026-27 guide; statutes and rules in it current as of July 1, 2024", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-id"}$kb$::jsonb
