-- dig-ak-overview-1 replaces dig-ak (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ak-overview-1", "state": "AK", "tier": "core", "title": "Alaska 811: the dig law in short (Alaska 811, Alaska Digline)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Alaska's dig law is AS 42.30.400 to 42.30.490. One center: Alaska 811 (Alaska Digline). Notice: \"at least two but not more than 15 working days\" before digging. Remote locations: at least 10 but not more than 20 working days. The law sets no ticket expiry. The handbook says most owners treat a ticket as expired if more than 15 calendar days pass before digging starts (20 in remote places). Marks gone from weather, construction or vandalism: ask for a remark, give the old dig number, and plan on another 2 working days. Mark the dig area in white; \"Black paint may be used when snow is on the ground.\" No digging until each line is field marked. Lines there but not located: call for a second request. Tolerance zone: the width of the line plus 2 feet on either side (30 inches for lines more than 10 feet deep). Hand dig or vacuum within 24 inches of a marked line. Hit a line: notify the utility and the one-call system right away; danger, clear out and call 911. Fines: $50 to $1,000 for each offense that causes or adds to damage.", "source": "Alaska 811 Excavator Handbook (2026) pp. 2-3, 6-8, 13-22; AS 42.30.400 to 42.30.490", "url": "https://cdn.pelicancorp.com/pdfs/26-ak811-excavator-handbook.pdf", "checked": "2026-11-20", "edition": "2026 handbook", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-ak"}$kb$::jsonb
