-- dig-nm-overview-1 replaces dig-nm (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-nm-overview-1", "state": "NM", "tier": "core", "title": "New Mexico 811: the dig rules in short (NM811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "New Mexico's dig law is the Excavation Damage to Pipelines and Underground Utility Lines Act (NMSA 62-14) with rule 18.60.5 NMAC, enforced by the Public Regulation Commission's pipeline safety bureau. One center: NM811. Notice: 2 working days, not counting the day you call; operators must mark \"within two full working days from the effective date of the ticket.\" Marks are good for 15 working days from the end of the notice period. Marks gone with no offsets: stop and ask for a relocate, only for the part still to dig, and say why. Jobs longer than 15 working days: ask for a wide area conference at least two working days ahead, write a work plan signed by all, and reaffirm the wide area ticket every 15 working days. Pre-mark in white: it shows the actual dig, not the limits of construction. Before digging, check that every operator has marked or cleared. If one has not, call for a warning locate. Within 18 inches either side of a mark, expose the line first by non-mechanical means or vacuum. Hit a line: stop, call 911 if needed, the operator and 811, secure the site, and stay until released.", "source": "18.60.5 NMAC sections 7, 8, 10, 11, 12, 13, 15, 16, 17 (Public Regulation Commission, srca.nm.gov)", "url": "https://www.srca.nm.gov/parts/title18/18.060.0005.html", "checked": "2026-11-20", "edition": "18.60.5 NMAC as posted Nov 20, 2026", "confidence": "high", "kind": "summary", "license": "gov-state", "supersedes": "dig-nm"}$kb$::jsonb
