-- dig-mn-overview-1 replaces dig-mn (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-mn-overview-1", "state": "MN", "tier": "core", "title": "Minnesota 811: the dig law in short (Gopher State One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Minnesota's dig law is Minn. Stat. chapter 216D, enforced by the Minnesota Office of Pipeline Safety. One center: Gopher State One Call (GSOC). Notice: at least 48 hours, not counting the day you file, weekends and holidays, and not more than 14 calendar days ahead. A ticket is good for 14 calendar days from the start date and time on it (up to six months when a marking schedule is agreed and written down). To go past 14 days, file an Update at least 48 hours (weekends and holidays not counted) before it expires; an Update gets a new ticket number and its own 48-hour wait. White marks are required: \"without exception.\" Electronic white marks count from January 1, 2026. Check GSOC's positive response before you dig. \"Not Yet Responded\" and no marks: contact that operator directly. Hand dig zone: 2 feet (24 inches) from each side of the line. Hand tools or vacuum only there. Hit a line: notify the owner right away; gas or liquid escaping, call 911. Never bury a damaged line.", "source": "Gopher State One Call Handbook 2026 pp. 14-28, 33-46, 76, 84; Minn. Stat. ch. 216D", "url": "https://gopherstateonecall.org/wp-content/uploads/GSOCHandbook2026.pdf", "checked": "2026-11-20", "edition": "2026 Handbook", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-mn"}$kb$::jsonb
