-- dig-sc-overview-1 replaces dig-sc (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-sc-overview-1", "state": "SC", "tier": "core", "title": "South Carolina 811: the dig law in short (SC811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "South Carolina's dig law is the Underground Facility Damage Prevention Act, S.C. Code Title 58, Chapter 36. One center: SC811. Wait: operators \"have three full working days to mark,\" not counting the day you call. A normal request is good for 15 working days from its start time. Send an Extension any time before it runs out; an Extension does not refresh the paint. Marks gone: send a Remark, which makes a new ticket with a new number and gives operators three full working days. Once a request has expired you need a new one. Pre-mark in white paint, flags or stakes when the site can't be clearly identified. Before digging, verify that every operator has answered in Positive Response. No answer and no sign of a line: you may proceed. Signs of a line: request a No Show; the operator has three hours. Tolerance zone: 24 inches on either side of the mark plus half the diameter if known. No machines there until you can see the line; machines may remove pavement only. Hit a line: notify SC811 and the operator right away; danger or a release, call 911 first.", "source": "SC811 Excavator Manual 2026 pp. 9-23, 27-35; S.C. Code 58-36-10 to 58-36-120", "url": "https://sc811.com/wp-content/uploads/2026/05/Excavator-Manual-2026.pdf", "checked": "2026-11-20", "edition": "2026 Excavator Manual", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-sc"}$kb$::jsonb
