-- dig-ok-overview-1 replaces dig-ok (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ok-overview-1", "state": "OK", "tier": "core", "title": "Oklahoma 811: the dig law in short (OKIE811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Oklahoma's dig law is the Underground Facilities Damage Prevention Act, 63 O.S. 142.1 to 142.13 (last amended November 1, 2024). The Corporation Commission enforces it for oil and gas pipelines. One center: OKIE811. Notice: at least 48 hours before digging, not counting the day you call, Saturdays, Sundays and legal holidays. Demolition: 7 business days. \"Notice shall expire fourteen (14) calendar days from the excavation start date.\" To keep going, update the ticket (Extend, or Re-Mark if marks are gone) at least 4 business days before it expires; operators get 48 hours to respond. A ticket covers no more than 500 linear feet in a city or town, or one linear mile outside. White line the dig area before you call. Check positive responses before starting. Operator missing: send a Second Notice. Approximate location: a strip two feet on either side of the line. Only hand digging there until the line is exposed; machines may remove pavement only. Hit a line: notify the operator and OKIE811 immediately; gas escaping, leave and call 911. Hold the backfill until repairs are done.", "source": "OKIE811 Excavator Guide (Feb 2026; law text as of Nov 1, 2025) pp. 6, 10-19, 24-39; 63 O.S. 142.6", "url": "https://okie811.org/wp-content/uploads/2026/07/2026-Excavator-Guide-Digital-.pdf", "checked": "2026-11-20", "edition": "Excavator Guide, February 2026", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-ok"}$kb$::jsonb
