-- dig-ia-overview-1 replaces dig-ia (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ia-overview-1", "state": "IA", "tier": "core", "title": "Iowa 811: the dig law in short (Iowa One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Iowa's dig law is Iowa Code chapter 480; the Attorney General enforces it. One center: Iowa One Call. Notice: \"at least forty-eight hours prior to the commencement\" of digging, not counting the notice day, weekends and legal holidays. A ticket is \"valid for twenty-five (25) calendar days beginning on the day the forty-eight-hour period concludes.\" There is no renewal: for a longer job, request a new locate ticket before the old one runs out. You can't dig on another excavator's ticket. Use white paint, flags or stakes to show the dig area unless it is clearly defined or you used electronic white-lining. Operators must post a positive response within the 48 hours. Check the Electronic Positive Response System before starting; if one is missing, contact the operator or Iowa One Call. Tolerance zone: 18 inches on either side of the line. Hand-dig test holes there; no machinery other than accepted methods such as vacuum excavation. Hit a line: tell the operator as soon as practical and do not backfill until it has looked; gas or liquid escaping, call 911.", "source": "Iowa One Call Excavator Manual (July 2024) pp. 2, 12-19, 32-46, 54-56; Iowa Code ch. 480", "url": "https://iowaonecall.com/wp-content/uploads/2024/08/iaoc-excavator-manual-2024.pdf", "checked": "2026-11-20", "edition": "Excavator Manual published July 2024", "confidence": "medium", "kind": "summary", "license": "summary", "supersedes": "dig-ia"}$kb$::jsonb
