-- dig-ms-overview-1 replaces dig-ms (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ms-overview-1", "state": "MS", "tier": "core", "title": "Mississippi 811: the dig law in short (Mississippi 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Mississippi's dig law is Miss. Code 77-13-1 and after, amended by HB 1191 effective July 1, 2025. One center: Mississippi 811 (MS811). Ticket life went \"from 14 to 20 calendar days\" for Normal, Emergency, Impending Emergency, Short Notice and Design tickets. Update at least 3 working days before a ticket expires so there is no gap. (MS811's older portal guide says an update adds 14 calendar days; whether that is now 20 is not confirmed.) The wait before digging was not on the page read and is not confirmed here: go by the dig date on your ticket. Tolerance zone: 18 inches plus one-half of the diameter of the line when the diameter is shown at the marks, measured from the outside edge of the marks. Use non-invasive methods there (hand digging, vacuum), support the line, and keep machines a safe distance away. Pre-mark in white unless you own the property and described it clearly, or you drew the dig area on the web portal map after MS811's short training. Emergency tickets: operators respond within 2 hours, and you must name a contact who will be on site. Large projects (can't be finished in 20 calendar days): optional preconstruction meeting and a signed agreement before work.", "source": "Mississippi 811 \"2025 Excavation Law Amendments Summary\" (HB 1191, effective July 1, 2025); MS811 Portal Update guide", "url": "https://ms811.org/wp-content/uploads/2025/04/2025-Excavation-Law-Amendments-Summary.pdf", "checked": "2026-11-20", "effective": "2025-07-01", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "wait before digging; days added by an update", "supersedes": "dig-ms"}$kb$::jsonb
