-- dig-sd-overview-1 replaces dig-sd (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-sd-overview-1", "state": "SD", "tier": "core", "title": "South Dakota 811: the dig law in short (South Dakota 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "South Dakota's dig law is SDCL chapter 49-7A, with the One-Call Notification Board writing the rules. One center: South Dakota 811. Notice (49-7A-5, 2026 Senate Bill 9): \"at least forty-eight hours prior to the commencement of the excavation.\" The 48 hours start at 12:01 a.m. the day after you send the notice and skip Saturdays, Sundays and state legal holidays. Operators mark within \"eighteen inches horizontally from the exterior sides of the underground facilities.\" Keep \"a minimum horizontal clearance of eighteen inches\" between the marked line and the cutting edge of any machine. If you must dig closer than 18 inches, expose the line first with hand tools or an approved noninvasive method, then protect and support it before using the machine again. How long a ticket lasts, the damage steps and the fine amounts were not in the text read and are not confirmed here: go by the ticket and South Dakota 811.", "source": "SDCL 49-7A-5 and 49-7A-8 as amended by 2026 Senate Bill 9 (enrolled)", "url": "https://mylrc.sdlegislature.gov/api/Documents/300764.pdf", "checked": "2026-11-20", "edition": "2026 Senate Bill 9, enrolled", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life, damage steps, fine amounts", "supersedes": "dig-sd"}$kb$::jsonb
