-- dig-wy-overview-1 replaces dig-wy (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-wy-overview-1", "state": "WY", "tier": "core", "title": "Wyoming 811: the dig law in short (One-Call of Wyoming)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Wyoming's dig law is the Wyoming Underground Facilities Notification Act, Wyo. Stat. 37-12-301 to 37-12-307. One center: One-Call of Wyoming (811). Notice: \"at least two (2) full business days, but not more than fourteen (14) business days prior to any excavation.\" A job that runs longer than 14 business days needs the notice given again for each following 14 business day period. Mark the dig area before the locator comes, unless one operator can find the site from the address, there was a site meeting, or it is an emergency. Operators mark \"within twenty-four (24) inches horizontally\" of the outside of the line, in APWA colors, within two full business days. Reasonable care is always required, and it calls for hand or soft digging where needed to protect the line. Hit or touch a line: notify the operator and the center immediately. Gas or hazardous liquid released: call 911 first. Do not hide damage or repair it without authorization. In a dispute the excavator has to prove reasonable care. If the operator missed its deadline or marked wrong, an excavator who used reasonable care is not liable. Penalty amounts were not confirmed.", "source": "Wyo. Stat. 37-12-302 (Counsel Stack copy, 2026)", "url": "https://law.counselstack.com/statute/wy/37-12-302", "checked": "2026-11-20", "edition": "Statute copy read Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "penalty amounts", "supersedes": "dig-wy"}$kb$::jsonb
