-- dig-hi-overview-1 replaces dig-hi (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-hi-overview-1", "state": "HI", "tier": "core", "title": "Hawaii 811: the dig law in short (Hawaii One Call Center)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Hawaii's dig law is HRS chapter 269E, under the Public Utilities Commission. One center: the Hawaii One Call Center (811). Notice: \"at least five working days but not more than twenty-eight calendar days prior to commencing excavation,\" except in an emergency. The center issues an inquiry identification number that \"shall remain valid for not more than twenty-eight calendar days from the date of issuance.\" Ask to revalidate it before it expires; you must hold a valid number for the whole time you are digging. No notice is needed on private property owned only by the excavator where no operator has lines. The center notifies the operators the same day. The tolerance zone, hand-dig rule, damage steps and fine amounts are in other sections (269E-12 to 269E-14) that were not read in this pass and are not confirmed here.", "source": "HRS 269E-7 (capitol.hawaii.gov)", "url": "https://data.capitol.hawaii.gov/hrscurrent/Vol05_Ch0261-0319/HRS0269E/HRS_0269E-0007.htm", "checked": "2026-11-20", "edition": "HRS current edition online, read Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "tolerance zone, damage steps, fine amounts", "supersedes": "dig-hi"}$kb$::jsonb
