-- dig-nd-overview-1 replaces dig-nd (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-nd-overview-1", "state": "ND", "tier": "core", "title": "North Dakota 811: the dig law in short (North Dakota One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "North Dakota's dig law is N.D.C.C. chapter 49-23. One center: North Dakota One Call (811). Notice: the handbook says \"at least 48 hours (excluding weekends and holidays)\" before digging. A ticket is good for 21 calendar days from the start time on it. The law says an excavator \"may not use a location more than twenty-one days\" after the planned dig date without arrangements with the operators; if no digging happened in the first 21 days, ask for a relocate first. After expiry, get a new ticket. There is no blanket ticket. One request covers at most three city blocks in town, or four quarter sections or five linear miles in the country. Show the site with white marking, digital white lining or project staking. Operators mark a strip two feet on either side of the line. Dig by hand within 24 inches of a located line. Emergency: call 911 first, then the utility, then the center. Hit a line: notify the operator promptly; danger, call 911 and keep people away. Knowing of damage and not reporting it, or backfilling over it, is a class A misdemeanor. Civil penalty up to $25,000. Farm work shallower than 18 inches and gardening shallower than 12 inches are not excavation.", "source": "N.D.C.C. 49-23-04 (Counsel Stack copy, 2026); ND One Call Locate Request Handbook (2020 copy) pp. 7-13, 21, 31-48", "url": "https://law.counselstack.com/statute/nd/49-23-04", "checked": "2026-11-20", "edition": "Statute copy read Nov 20, 2026; handbook 2020", "confidence": "medium", "kind": "summary", "license": "gov-state", "supersedes": "dig-nd"}$kb$::jsonb
