-- dig-ar-overview-1 replaces dig-ar (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ar-overview-1", "state": "AR", "tier": "core", "title": "Arkansas 811: the dig law in short (Arkansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Arkansas's dig law is the Arkansas Underground Facilities Damage Prevention Act, Ark. Code 14-271-101 and after. One center: Arkansas 811. Notice (14-271-112): \"at least two (2), but not more than ten (10), full working days before commencing\" the dig. The notice is \"effective for a period of twenty (20) working days from the date that the notice was given.\" Work not finished or marks gone: \"reinitiate the notice procedure,\" which means calling it in again with the normal wait. The tolerance zone, white lining rule, damage steps and fine amounts were not read in this pass and are not confirmed here. Until they are: hand dig or vacuum to find any marked line before a machine works near it, and if you hit a line call the owner, and 911 if gas or liquid is escaping.", "source": "Ark. Code 14-271-112 (FindLaw copy, current as of Mar 28, 2024, as quoted in tests/staged/locate_round3_nov20/raw_findings.md)", "url": "https://codes.findlaw.com/ar/title-14-local-government/ar-code-sect-14-271-112/", "checked": "2026-11-20", "edition": "FindLaw copy current as of March 28, 2024", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "tolerance zone, white lining, damage steps, fine amounts", "supersedes": "dig-ar"}$kb$::jsonb
