update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-mt-overview-1", "state": "MT", "tier": "core", "title": "Montana 811: not confirmed yet: what to check with Montana 811", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Montana's dig law is Mont. Code Title 69, Chapter 4, Part 5 (underground facility protection). One center: Montana 811. None of Montana's numbers could be opened in an official source in this pass, so they are not confirmed: the wait before digging, how long a ticket lasts, the tolerance zone and the fines. Do not use another state's numbers. What to do: call 811 or go online at montana811.org before any digging, start only on or after the dig date printed on the ticket, check that every utility on the ticket has marked or cleared, and ask Montana 811 how long the ticket is good for on a long job. The federal rule applies everywhere for pipelines: use one-call first, wait for the marks, dig with care, report any pipeline damage to the operator, and call 911 if gas or hazardous liquid is released (49 CFR 196).", "source": "Mont. Code 69-4-501 to 69-4-530 (not opened); 49 CFR 196.103 to 196.109", "url": "https://www.ecfr.gov/current/title-49/subtitle-B/chapter-I/subchapter-D/part-196", "checked": "2026-11-20", "edition": "Not confirmed; federal rule current to Oct 22, 2026", "confidence": "low", "kind": "summary", "license": "gov-state", "unconfirmed": "all state numbers", "supersedes": "dig-mt"}$kb$::jsonb
