update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-wi-overview-1", "state": "WI", "tier": "core", "title": "Wisconsin 811: the dig law in short (Diggers Hotline)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "text": "Wisconsin's dig law is Wis. Stat. 182.0175. One center: Diggers Hotline (811). A Public Service Commission panel hears complaints. Notice: \"not less than 3 working days before the start of nonemergency excavation.\" Working days are days other than Saturday, Sunday and legal holidays. There is no set ticket life. Give a new notice if the dig does not start \"within 10 days of the scheduled start date,\" if marks are destroyed or covered, or if work stops for more than 10 days. Keep \"an estimated minimum clearance of 18 inches\" between a marked, unexposed line and the cutting edge of the machine. Once the line is exposed the clearance can drop to twice the machine's limit of control or 12 inches, whichever is greater. Owners mark within 3 working days in the ANSI uniform colors. Before backfilling, inspect any line you exposed. If a line may be damaged, notify the owner immediately and do not backfill until it has been inspected. Gas or liquid that may endanger life: call 911. Emergency: take all reasonable precautions and notify owners as promptly as possible. Fine amounts were not confirmed.", "source": "Wis. Stat. 182.0175(1), (2), (2m), (3) (docs.legis.wisconsin.gov)", "url": "https://docs.legis.wisconsin.gov/statutes/statutes/182/0175/2?up=1", "checked": "2026-11-20", "edition": "Wisconsin Statutes online, read Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "fine amounts", "supersedes": "dig-wi"}$kb$::jsonb
